                    // from the server panel, with Back (Members and Computers are on the panel now,
                    // so they no longer lead it); its rows keep their attention dots. The wide rail
                    // keeps its Settings page as before.
                    val settingsTabContent: @Composable (active: Boolean) -> Unit = {
                        SettingsAppShellHomeContent(
                            moreRoot =
                                if (navRailActive) {
                                    null
                                } else {
                                    SettingsMoreRoot(
                                        title = settingsTabLabel,
                                        membersTitle = membersTabLabel,
                                        attentionRowKeys = moreAttention.mapTo(mutableSetOf()) { it.settingsRowKey },
                                        leadsWithMembersAndComputers = false,
                                    )
                                },
                            onBack = moreChildBack,
                            session = (authGateState as? SharedAuthGateState.Ready)?.session,
                            bottomContentPadding = appShellBottomContentInset,
                            scrollToTopRequest = tabScrollToTopRequests.more,
                            onSettingsHeaderClick = {
                                prewarmAdmissionGate.invalidate("settings_header")
                                val nextTapCount = settingsHeaderTapCount + 1
                                if (nextTapCount >= SettingsDeveloperUnlockTapCount) {
                                    settingsHeaderTapCount = 0
                                    pager.openSettingsNativeDetailPage(SettingsNativeDetailPage.Developer, storeScope)
                                } else {
                                    settingsHeaderTapCount = nextTapCount
                                }
                            },
                            onSelect = { key ->
                                prewarmAdmissionGate.invalidate("settings_open_page:$key")
                                settingsHeaderTapCount = 0
                                when (key) {
                                    SettingsMoreMembersRowKey -> {
                                        RaftProductEvents.navEntrySelected(
                                            destination = RaftNavDestination.Members,
                                            surface = RaftNavSurface.MobileMore,
                                            wasActive = false,
                                        )
                                        bridge.log("app_shell_more_open row=$key from=$selectedTab")
                                        selectAppShellTab("members", directChildSwitch = true)
                                        retainedAppShellTabs = retainedAppShellTabs + "members"
                                    }
                                    SettingsDestinationAccount -> pager.openSettingsAccountPage(storeScope)
                                    SettingsDestinationStorage -> pager.openSettingsStoragePage(storeScope)
                                    SettingsDestinationReleaseNotes -> pager.openReleaseNotesPage(storeScope = storeScope)
                                    SettingsDestinationBilling -> pager.openSettingsBillingPage(storeScope)
                                    SettingsDestinationComputers -> {
                                        if (!navRailActive) {
                                            RaftProductEvents.navEntrySelected(
                                                destination = RaftNavDestination.Computers,
                                                surface = RaftNavSurface.MobileMore,
                                                wasActive = false,
                                            )
                                        }
                                        openComputersPage()
                                    }
                                    SettingsDestinationAdministration -> pager.openSettingsAdministrationPage(storeScope)
                                    SettingsDestinationConnectedApps -> pager.openSettingsMarketplacePage(storeScope)
                                    SettingsDestinationHandsFeedback ->
                                        if (sharedStores.serverFeatureFlags.isEnabled(readyServerId?.let(::ServerId), PRODUCT_FEEDBACK_MULTI_APP_FEATURE_FLAG_KEY)) {
                                            pager.openSettingsFeedbackWebViewPage(storeScope)
                                        } else {
                                            pager.openSettingsHandsFeedbackPage(storeScope)
                                        }
                                    else -> {
                                        val page = SettingsNativeDetailPage.fromKey(key)
                                        if (page == null || !pager.openSettingsNativeDetailPage(page, storeScope)) {
                                            bridge.logWarn("settings_native_detail_rejected page=$key")
                                        }
                                    }
                                }
                            }
                        )
                    }
                    val currentChildTab = retainedAppShellSelectedTab(selectedTab)
                    val moreTabContent: @Composable (active: Boolean) -> Unit = { active ->
                        PerformanceSceneEffect(bridge, "kuikly_more", active = active)
                        settingsTabContent(active)
                    }
                    // stdrc 2026-10-21 (option B): the phone Search tab. A tab root (no Back, the bar
                    // stays); a result pushes its page over the shell and Back returns here with the
                    // query, results and scroll kept (the tab stays composed like the others).
                    // The field never autofocuses (nav spec: the first switch shows the tab with the bar);
                    // tapping it or re-tapping the selected Search tab focuses it. While the tab is not
                    // shown its field holds neither focus nor the IME.
                    val searchTabContent: @Composable (active: Boolean) -> Unit = { active ->
                        HomeSecondaryRouterContent(
                            destination = HomeDestinationSearch,
                            routeVisibleTick = pageVisibleTick,
                            initialSearchFocusInput = false,
                            searchInputActive = active,
                            searchFocusInputRequest = searchTabFocusInputRequest,
                            searchQueryRequest = searchTabQueryRequest,
                            onSearchQueryApplied = { searchTabQueryRequest = null },
                            adaptivePane = shellScope.adaptivePane,
                            tabRoot = true,
                            hostPager = pager,
                            searchListState = searchTabListState,
                            searchReturnHighlight = searchTabReturnHighlight,
                            searchBottomContentPadding = appShellBottomContentInset,
                        )
                    }
                    val childTabRenderer: AppShellChildTabRenderer = { tab, active ->
                        val homeSummary = sharedHomeContentRenderSummary(homeState.content)
                        LaunchedEffect(tab, active, currentChildTab, readyServerId, homeSummary, homeState.homeRealtimeDirty) {
                            bridge.log(
                                "app_shell_child_tab_dispatch tab=$tab active=$active selectedTab=$currentChildTab " +
                                    "readyServerId=${readyServerId.orEmpty()} homeState=$homeSummary " +
                                    "homeRealtimeDirty=${homeState.homeRealtimeDirty}"
                            )
                        }
                        CompositionLocalProvider(LocalRaftTimeContextProvider provides hostThreadTimeContextProvider) {
                            when (tab) {
                                "home" -> homeTabContent(active)
                                "tasks" -> tasksTabContent(active)
                                "members" -> membersTabContent(active)
                                "settings" -> settingsTabContent(active)
                                "dms" -> dmsTabContent(active)
                                "activity" -> activityTabContent(active)
                                "more" -> moreTabContent(active)
                                AppShellSearchTabKey -> searchTabContent(active)
                                else -> homeTabContent(active)
                            }
                        }
                    }
                    val childTabRegistration =
                        remember(childTabShellId, slackNavTabKeys) {
                            val entry = AppShellChildTabEntry(
                                debugId = AppShellChildTabRegistry.createEntryId(),
                                timestampDisplayState = timestampDisplayState,
                                initialSelectedTab = currentChildTab,
                                initialParentVisible = pageVisible,
                                initialRetainedTabs = retainedAppShellTabs,
                                initialRenderer = childTabRenderer,
                                // task #94: the render-slot map follows the resolved ordered
                                // keys; a gate flip re-registers the entry with the new set.
                                initialTabKeys = slackNavTabKeys,
                                initialModalHostState = appShellModalHostState
                            )
                            val replaced = AppShellChildTabRegistry.register(childTabShellId, entry)
                            AppShellChildTabRegistration(entry = entry, replacedEntryId = replaced?.debugId ?: 0)
                        }
                    val childTabEntry = childTabRegistration.entry
                    SideEffect {
                        childTabEntry.updateSelection(
                            selectedTab = currentChildTab,
                            parentVisible = pageVisible,
                            retainedTabs = retainedAppShellTabs,
                            renderer = childTabRenderer
                        )
                        childTabEntry.modalHostState = appShellModalHostState
                    }
                    LaunchedEffect(childTabShellId, childTabEntry.debugId) {
                        bridge.log(
                            "app_shell_child_tab_registry_register shellId=$childTabShellId " +
                                "entryId=${childTabEntry.debugId} replacedEntryId=${childTabRegistration.replacedEntryId} " +
                                "selectedTab=${childTabEntry.selectedTab}"
                        )
                    }
                    DisposableEffect(childTabShellId, childTabEntry) {
                        onDispose {
                            val removed = AppShellChildTabRegistry.unregister(childTabShellId, childTabEntry)
                            bridge.log(
                                "app_shell_child_tab_registry_unregister shellId=$childTabShellId " +
                                    "entryId=${childTabEntry.debugId} removed=$removed"
                            )
                        }
                    }
                    // task #13 three-pane: a rail secondary destination (Search) replaces the
                    // tab host's middle area with its own list pane; the shared workspace
                    // detail slot to its right keeps working via adaptiveSplitListDetail.
                    // Narrow or flag-off never reaches here — the push path handles those.
                    // The inline Search / Saved lists mark the row whose conversation is open in
                    // the detail beside them, like Home and Activity (one selection per list: their
                    // row keys are not shared).
                    val railInlineSearchSelection =
                        remember { RaftInlineListSelection { adaptiveWorkspaceStore.snapshot().workspace?.selection?.identity?.key } }
                    val railInlineSavedSelection =
                        remember { RaftInlineListSelection { adaptiveWorkspaceStore.snapshot().workspace?.selection?.identity?.key } }
                    val railInlineOpenDetailKey = adaptiveWorkspaceState?.selection?.identity?.key
                    SideEffect {
                        railInlineSearchSelection.openDetailKey = railInlineOpenDetailKey
                        railInlineSavedSelection.openDetailKey = railInlineOpenDetailKey
                    }
                    val railInlineDestination =
                        when (railInlineSecondaryDestination) {
                            AppShellRailSearchKey -> HomeDestinationSearch
                            AppShellRailSavedKey -> HomeDestinationSaved
                            else -> null
                        }
                    if (railInlineDestination != null) {
                        val searchListPane: @Composable (Boolean) -> Unit = { listActive ->
                            HomeSecondaryRouterContent(
                                destination = railInlineDestination,
                                routeVisibleTick = pageVisibleTick,
                                initialSearchFocusInput = false,
                                adaptivePane = shellScope.adaptivePane,
                                searchQueryRequest = searchTabQueryRequest.takeIf { railInlineDestination == HomeDestinationSearch },
                                onSearchQueryApplied = { searchTabQueryRequest = null },
                                inlineListSelection =
                                    if (railInlineDestination == HomeDestinationSearch) {
                                        railInlineSearchSelection
                                    } else {
                                        railInlineSavedSelection
                                    },
                                inlineOpenRequest = { request, source ->
                                    openHomeMessageRequest(request, source)
                                },
                                inlineOnClose = {
                                    // Same ordering as popMainRoute: a mounted detail
                                    // closes before the inline Search destination exits.
                                    // Read the store snapshot, not the compose state: the
                                    // remember-keyed environment may hold this lambda across
                                    // recompositions, so only the store has the live truth.
                                    val liveSelection =
                                        adaptiveWorkspaceStore.snapshot().workspace?.selection
                                    val dismissFirst =
                                        appShellRailSurfaceBackDismissesDetailFirst(
                                            selectedTab = selectedTab,
                                            railInlineSecondaryDestination = railInlineSecondaryDestination,
                                            selectionPresent = liveSelection != null,
                                        )
                                    bridge.log(
                                        "rail_inline_secondary_close destination=$railInlineSecondaryDestination " +
                                            "selectedTab=$selectedTab dismissFirst=$dismissFirst " +
                                            "selection=${liveSelection?.identity?.key.orEmpty()}"
                                    )
                                    if (dismissFirst) {
                                        dismissAdaptiveDetailSelection()
                                    } else {
                                        railInlineSecondaryDestination = null
                                    }
                                },
                                inlineOpenEntity = { entity ->
                                    when (entity.destinationOrNull()) {
                                        is HomeSearchEntityDestination.Conversation -> {
                                            // Conversation entities open in the shared detail
                                            // pane; everything else still needs a full page.
                                            val destination =
                                                entity.destinationOrNull()
                                                    as HomeSearchEntityDestination.Conversation
                                            openHomeConversation(
                                                conversation = destination.identity,
                                                source = "home_search_entity",
                                            )
                                            true
                                        }
                                        else -> false
                                    }
                                },
                            )
                        }
                        adaptiveSplitListDetail(
                            desktopModeOnLargeScreen,
                            pageVisible,
                            searchListPane,
                            true,
                        )
                    } else {
                    AppShellTabPager(
                        selectedTab = selectedTab,
                        pageVisible = pageVisible,
                        childHostShellId = childTabShellId,
                        mountedTabs = retainedAppShellTabs + prewarmedAppShellTabs,
                        childTabSwitchEpoch = childTabSwitchEpoch,
                        childPageTabKeys = slackNavTabKeys,
                        log = { bridge.log(it) }
                    ) { tab, active ->
                        CompositionLocalProvider(LocalRaftTimeContextProvider provides hostThreadTimeContextProvider) {
                            when (tab) {
                                "settings" -> settingsTabContent(active)
                                else -> childTabRenderer(tab, active)
                            }
                        }
                    }
                    }
            Box(modifier = Modifier.fillMaxSize()) {
                if (createJointChannelDialogOpen) {
                    val jointHomeSnapshot = (homeState.content as? SharedHomeContentState.Content)?.snapshot
                    CreateJointChannelDialogHost(
                        networkClient = appShellNetworkClient,
                        // Web `freeAllowance`: the current server's plan is "free".
                        freePlan = (jointHomeSnapshot?.server?.plan ?: "free") == "free",
                        currentServerSlug = jointHomeSnapshot?.server?.slug,
                        currentMemberId = jointHomeSnapshot?.currentMember?.id?.value,
                        members = createChannelMembers,
                        membersLoading = createChannelMembersLoading,
                        logger = raftLogger("SlockCreateJointChannel", "create_joint_channel", RaftLogLevel.Warn),
                        onDismiss = { createJointChannelDialogOpen = false },
                        onOpenChannel = { channel ->
                            createJointChannelDialogOpen = false
                            homeShellStore.dispatch(SharedHomeShellIntent.Home(SharedHomeIntent.Refresh))
                            openHomeConversation(
                                buildThreadLaunchConversationIdentity(
                                    kind = ConversationKind.Joint,
                                    channelId = channel.channelId,
                                    channelType = "joint",
                                ),
                                "create_joint_channel",
                            )
                        },
                        onOpenBilling = {
                            createJointChannelDialogOpen = false
                            pager.openSettingsBillingPage(storeScope)
                        },
                    )
                }
                if (createChannelDialogOpen) {
                    SharedCreateChannelDialog(
                        submitting = createChannelSubmitting,
                        membersLoading = createChannelMembersLoading,
                        members = createChannelMembers,
                        errorMessage = createChannelError,
                        agentStatusResolver = createChannelAgentStatusResolver,
                        onDismiss = {
                            if (!createChannelSubmitting) {
                                createChannelDialogOpen = false
                                createChannelError = null
                            }
                        },
                        onSubmit = { name, description, visibility, agentMemberIds, userMemberIds ->
                            submitCreateChannel(name, description, visibility, agentMemberIds, userMemberIds)
                        }
                    )
                }
                activeAnnouncement?.let { announcement ->
                    val announcementWebBase = sharedStores.apiEnvironmentStore.current().webUrl.trimEnd('/')
                    SharedAnnouncementModal(
                        announcement = announcement,
                        onDismiss = {
                            if (announcementStore.dismiss(announcement.id)) {
                                appShellCoroutineScope.launch {
                                    announcementStore.persistDismissal(announcement.id)
                                }
                            }
                        },
                        onOpenUrl = { url ->
                            if (announcementOwner == latestAnnouncementOwner) {
                                resolveAnnouncementLink(
                                    url,
                                    announcementWebBase,
                                    readySession?.servers?.firstOrNull { it.id == readyServerId }?.slug,
                                )?.let { linkNavigator.open(it) }
                            }
                        }
                    )
                }
            }
        }
    }

    val mainRouteContent: @Composable () -> Unit = {
        if (serverDrawerEnabled) {
            AppShellServerDrawerHost(
                homeShellStore = homeShellStore,
                bridge = bridge,
                labels = appShellHomeLabels,
                userHeader = serverDrawerUserHeader,
                topSafeArea = shellScope.topSafeArea,
                bottomSafeArea = shellScope.bottomSafeArea,
                serverMembersStore = appShellServerMembersStore,
                serverActivityExpectedOwner = serverActivityExpectedOwner,
                selectedTab = selectedTab,
                modalGestureBlocked =
                    appShellModalHostState.entries.isNotEmpty() ||
                        createChannelDialogOpen ||
                        activeAnnouncement != null,
                dismissLabel = stringResource(MR.strings.common_dismiss),
                onServerClick = ::openServerDrawerHome,
                onConversationClick = ::openServerDrawerConversation,
                onProgrammaticCloseFenceChanged = { serverDrawerProgrammaticCloseFence = it },
                content = mainRouteSurface
            )
        } else {
            mainRouteSurface()
        }
    }

    Box(modifier = Modifier.fillMaxSize()) {
        RaftForegroundBannerHost(
            banner = foregroundMessageBanner,
            topSafeArea = shellScope.topSafeArea,
            serverMembersStore = appShellServerMembersStore,
            currentServerStore = sharedStores.localDataStore,
            currentServerIdOverride = readySession?.currentServerId?.let(::ServerId),
            onBannerClick = { target ->
                foregroundBannerStore.dismiss(target.id)
                openHomeMessageRequest(
                    request = target.openRequest,
                    source = "foreground_banner",
                    fallbackAnchorMessageId = target.focusedMessageId
                )
            },
            onBannerDismiss = { target -> foregroundBannerStore.dismiss(target.id) }
        ) {
            key("route-main") { mainRouteContent() }
        }
        ExternalShareLaunchHost(
            pageData = pager.pageData.params,
            authStore = shellAuthStore,
            networkClient = appShellNetworkClient,
            authority =
                readySession?.let { session ->
                    ExternalShareLaunchAuthority(
                        accountId = session.user.id,
                        serverId = session.currentServerId.orEmpty(),
                        servers =
                            session.servers.map { server ->
                                build.raft.app.data.ExternalShareServerOption(
                                    id = server.id,
                                    title = server.name,
                                    slug = server.slug
                                )
                            }
                    )
                },
            bridge = bridge,
            onOpenComposer = ::openExternalShareComposer
        )
    }
}

internal fun SharedHomeShellState.withoutServerDrawerRuntimeForAppShellRender(): SharedHomeShellState =
    copy(
        home =
            home.copy(
                serverSwitcherExpanded = false,
                serverDrawer = HomeServerDrawerState(),
                serverDrawerCommandIntent = build.raft.app.data.HomeServerDrawerCommandIntent()
            )
    )

private data class AppShellServerDrawerProjection(
    val commandIntent: build.raft.app.data.HomeServerDrawerCommandIntent,
    val drawer: HomeServerDrawerState,
    val unreadCounts: Map<String, Int>,
    val activityUnread: HomeServerActivityUnreadProjection,
)

private data class DrawerSettledObservation(
    val isOpen: Boolean,
    val progress: Float
)

private fun DrawerSettledObservation.isSettled(desiredOpen: Boolean): Boolean =
    if (desiredOpen) isOpen && progress >= 0.99f else !isOpen && progress <= 0.01f

@Composable
@OptIn(ExperimentalComposeUiApi::class)
private fun AppShellServerDrawerHost(
    homeShellStore: SharedHomeShellStore,
    bridge: build.raft.app.base.BridgeModule,
    labels: RaftHomeShellLabels,
    userHeader: RaftServerDrawerUserHeader,
    topSafeArea: Dp,
    bottomSafeArea: Dp,
    serverMembersStore: SharedServerMembersStore?,
    serverActivityExpectedOwner: ReadReceiptOwner?,
    selectedTab: String,
    modalGestureBlocked: Boolean,
    dismissLabel: String,
    onServerClick: (String) -> Unit,
    onConversationClick: (String, String) -> Unit,
    onProgrammaticCloseFenceChanged: (((String) -> Unit)?) -> Unit,
    content: @Composable () -> Unit
) {
    val projectionFlow =
        remember(homeShellStore) {
            homeShellStore.state
                .map { shellState ->
                    AppShellServerDrawerProjection(
                        commandIntent = shellState.home.serverDrawerCommandIntent,
                        drawer = shellState.home.serverDrawer,
                        unreadCounts = shellState.home.serverUnreadCounts,
                        activityUnread = shellState.home.serverActivityUnread,
                    )
                }
                .distinctUntilChanged()
        }
    val initialProjection =
        remember(homeShellStore) {
            val home = homeShellStore.state.value.home
            AppShellServerDrawerProjection(
                home.serverDrawerCommandIntent,
                home.serverDrawer,
                home.serverUnreadCounts,
                home.serverActivityUnread,
            )
        }
    val projection by projectionFlow.collectAsState(initialProjection)
    val currentIntent by rememberUpdatedState(projection.commandIntent)
    val drawerSections =
        remember(
            projection.drawer,
            projection.unreadCounts,
            projection.activityUnread,
            serverActivityExpectedOwner,
        ) {
            projection.drawer.toRaftHomeServerDrawerHostedSections(
                serverUnreadCounts = projection.unreadCounts,
                activityExpectedOwner = serverActivityExpectedOwner,
                activityProjection = projection.activityUnread,
            )
        }

    BoxWithConstraints(modifier = Modifier.fillMaxSize()) {
        val drawerWidth = homeServerDrawerWidth(maxWidth = maxWidth, maxHeight = maxHeight)
        val drawerState =
            rememberRaftMoveableDrawerState(
                initiallyOpen = false,
                drawerWidth = drawerWidth
            )
        val scrimWidth = (maxWidth - drawerWidth * drawerState.progress).coerceAtLeast(0.dp)
        // The drawer slides the shell (and its Compose bar) aside; the iOS system tab bar stays
        // put above the page, so it hides while any of the drawer shows.
        RaftNativeTabBarCover(active = drawerState.progress > 0.01f)
        var commandState by remember(drawerState) { mutableStateOf(HomeServerDrawerCommandState()) }
        val pointerPolicy = commandState.pointerPolicy(projection.commandIntent)
        val openGestureAdmission =
            HomeServerDrawerOpenGestureAdmission(
                homeSurfaceActive = selectedTab == "home",
                pointerOwnerActive = pointerPolicy.appEdgeEnabled,
                modalPresented = modalGestureBlocked
            )

        fun requestProgrammaticClose(source: String) {
            if (!currentIntent.desiredOpen) return
            commandState = commandState.beginProgrammaticClose()
            bridge.log(
                "server_drawer_programmatic_close_fenced generation=${currentIntent.generation} source=$source"
            )
            homeShellStore.dispatch(SharedHomeShellIntent.Home(SharedHomeIntent.DismissServerSwitcher))
        }
        val currentCloseRequest by rememberUpdatedState<(String) -> Unit> { source ->
            requestProgrammaticClose(source)
        }
        val programmaticCloseFence = remember {
            { source: String -> currentCloseRequest(source) }
        }
        DisposableEffect(programmaticCloseFence, onProgrammaticCloseFenceChanged) {
            onProgrammaticCloseFenceChanged(programmaticCloseFence)
            onDispose { onProgrammaticCloseFenceChanged(null) }
        }

        LaunchedEffect(drawerState, projection.commandIntent.generation) {
            val intent = projection.commandIntent
            if (intent.generation == 0L && !intent.desiredOpen) return@LaunchedEffect
            val generation = intent.generation
            commandState = commandState.pendingAdmission(intent)
            bridge.log(
                "server_drawer_command_pending_admission generation=$generation desiredOpen=${intent.desiredOpen} " +
                    "selectedTab=$selectedTab progress=${drawerState.progress}"
            )
            if (intent.desiredOpen) drawerState.open() else drawerState.close()
            if (currentIntent.generation != generation || currentIntent.desiredOpen != intent.desiredOpen) {
                return@LaunchedEffect
            }
            commandState = commandState.markSubmitted(generation, intent.desiredOpen)
            bridge.log(
                "server_drawer_command_submitted generation=$generation desiredOpen=${intent.desiredOpen} " +
                    "selectedTab=$selectedTab progress=${drawerState.progress}"
            )
            snapshotFlow { DrawerSettledObservation(drawerState.isOpen, drawerState.progress) }
                .first { observation -> observation.isSettled(intent.desiredOpen) }
            if (currentIntent.generation != generation || currentIntent.desiredOpen != intent.desiredOpen) {
                return@LaunchedEffect
            }
            val previousInteractive = commandState.interactiveGeneration
            commandState = commandState.settle(generation, intent.desiredOpen)
            if (commandState.interactiveGeneration == generation && previousInteractive != generation) {
                bridge.log(
                    "server_drawer_interactive generation=$generation " +
                        "rowKey=${commandState.interactiveRowKey.orEmpty()} selectedTab=$selectedTab"
                )
            }
            bridge.log(
                "server_drawer_command_settled generation=$generation terminal=" +
                    "${if (intent.desiredOpen) "settled_open" else "settled_closed"} " +
                    "isOpen=${drawerState.isOpen} progress=${drawerState.progress}"
            )
        }

        LaunchedEffect(drawerState) {
            snapshotFlow { DrawerSettledObservation(drawerState.isOpen, drawerState.progress) }
                .collect { observation ->
                    if (observation.isSettled(desiredOpen = false)) {
                        val previousDismissCount = commandState.gestureDismissCount
                        val generation = commandState.currentIntent.generation
                        commandState =
                            commandState
                                .establishClosedOwner(currentIntent)
                                .nativeSettledClosedWithoutCommand()
                        if (commandState.gestureDismissCount > previousDismissCount) {
                            bridge.log("server_drawer_gesture_closed generation=$generation")
                            homeShellStore.dispatch(SharedHomeShellIntent.Home(SharedHomeIntent.DismissServerSwitcher))
                        }
                    }
                }
        }

        Box(modifier = Modifier.fillMaxSize()) {
            RaftMoveableDrawer(
                state = drawerState,
                scrimColor = Color.Transparent,
                userScrollEnabled = pointerPolicy.nativePagerEnabled,
                drawerContent = {
                    HomeServerDrawerHostedPanel(
                        sections = drawerSections,
                        labels = labels,
                        userHeader = userHeader,
                        topSafeArea = topSafeArea,
                        bottomSafeArea = bottomSafeArea,
                        serverMembersStore = serverMembersStore,
                        rowObservationGeneration =
                            commandState.currentIntent.generation.takeIf {
                                commandState.currentIntent.desiredOpen &&
                                    commandState.phase in
                                        setOf(
                                            HomeServerDrawerCommandPhase.SubmittedOpen,
                                            HomeServerDrawerCommandPhase.SettledOpen
                                        )
                            },
                        interactiveGeneration = commandState.interactiveGeneration,
                        authoritativeOpenGeneration =
                            projection.commandIntent.generation.takeIf { projection.commandIntent.desiredOpen },
                        onServerClick = onServerClick,
                        onSectionToggle = { serverId ->
                            homeShellStore.dispatch(
                                SharedHomeShellIntent.Home(
                                    SharedHomeIntent.ToggleServerDrawerSection(ServerId(serverId))
                                )
                            )
                        },
                        onRetry = { serverId ->
                            homeShellStore.dispatch(
                                SharedHomeShellIntent.Home(SharedHomeIntent.RetryServerDrawerSection(ServerId(serverId)))
                            )
                        },
                        onConversationClick = { generation, serverId, conversationId ->
                            if (commandState.acceptsConversationClick(generation, currentIntent)) {
                                commandState = commandState.beginProgrammaticClose()
                                onConversationClick(serverId, conversationId)
                            }
                        },
                        onFirstInteractiveRow = { generation, rowKey ->
                            if (!commandState.acceptsRowObservation(generation, currentIntent)) {
                                return@HomeServerDrawerHostedPanel
                            }
                            val previousInteractive = commandState.interactiveGeneration
                            commandState = commandState.rowLaidOut(generation, rowKey)
                            if (commandState.interactiveGeneration == generation && previousInteractive != generation) {
                                bridge.log(
                                    "server_drawer_interactive generation=$generation rowKey=$rowKey selectedTab=$selectedTab"
                                )
                            }
                        }
                    )
                },
                content = {
                    val contentAccessibilityModifier =
                        if (drawerState.progress > 0.01f) {
                            Modifier.clearAndSetSemantics { invisibleToUser() }
                        } else {
                            Modifier
                        }
                    Box(
                        modifier =
                            Modifier
                                .fillMaxSize()
                                .then(contentAccessibilityModifier)
                    ) {
                        CompositionLocalProvider(
                            LocalRaftHomeDrawerOpenGesture provides
                                RaftHomeDrawerOpenGesture(
                                    admission = openGestureAdmission,
                                    onOpen = {
                                        if (
                                            selectedTab == "home" &&
                                            pointerPolicy.appEdgeEnabled &&
                                            !modalGestureBlocked &&
                                            !currentIntent.desiredOpen
                                        ) {
                                            commandState = commandState.beginProgrammaticOpen()
                                            bridge.log(
                                                "server_drawer_input source=app_shell_content selectedTab=$selectedTab"
                                            )
                                            homeShellStore.dispatch(
                                                SharedHomeShellIntent.Home(
                                                    SharedHomeIntent.ToggleServerSwitcher
                                                )
                                            )
                                        }
                                    }
                                )
                        ) {
                            content()
                        }
                    }
                }
            )
            if (drawerState.progress > 0.01f) {
                Box(
                    modifier =
                        Modifier
                            .align(Alignment.CenterEnd)
                            .fillMaxHeight()
                            .width(scrimWidth)
                            .background(Color.Black.copy(alpha = 0.28f * drawerState.progress)) // raft-color: drawer dimming scrim, black in both modes
                            .semantics {
                                contentDescription = dismissLabel
                                traversalIndex = 1f
                            }
                            .clickable(
                                interactionSource = remember { MutableInteractionSource() },
                                indication = null,
                                role = Role.Button
                            ) {
                                requestProgrammaticClose("scrim_compose")
                            }
                )
            }
        }
    }
}

internal fun appShellAuthGateViewModelKey(pagerId: String, instanceId: String = ""): String =
    "shared-auth-gate-${instanceId.ifBlank { pagerId }.ifBlank { "default" }}"

@Composable
internal fun SettingsNativeDetailScreen() {
    RememberKmmResourceLocaleSeedFromLocalActivity()
    val pager = LocalActivity.current.getPager() as Pager
    val bridge = remember(pager.pagerId) { Utils.bridgeModule(pager.pagerId) }
    val route = remember(pager.pageData.params.toString()) {
        settingsNativeDetailRoute(pager.pageData.params)
    }
    val closePage = remember(pager) {
        { pager.acquireModule<RouterModule>(RouterModule.MODULE_NAME).closePage() }
    }
    if (route == null) {
        SettingsDetailShell(
            title = stringResource(MR.strings.settings_title),
            subtitle = "",
            iconName = RaftLucideIconName.Settings,
            onBack = closePage,
        ) {
            SettingsSharedPlaceholder(
                title = stringResource(MR.strings.settings_title),
                detail = stringResource(MR.strings.empty_no_settings_available),
                iconName = RaftLucideIconName.Settings,
            )
        }
        return
    }

    val environment = rememberStandaloneSettingsEnvironment(pager, bridge)
    val sharedStores = remember(bridge) { RaftSharedStoreRegistry.get(bridge) }
    val settingsViewModel: SharedSettingsViewModel =
        viewModel(key = "standalone-settings-native-${pager.pagerId}") {
            SharedSettingsViewModel(
                environment.dataSource,
                diagnosticsLogger = { message -> bridge.log("settings_native_detail $message") }
            )
        }
    val settingsState by settingsViewModel.state.collectAsState()
    var session by remember { mutableStateOf<StoredAuthSession?>(null) }
    var notificationPreferenceSnapshot by remember {
        mutableStateOf(NotificationPreferenceSnapshot(enabled = true))
    }
    var activitySenderAvatarsEnabled by remember { mutableStateOf(false) }
    val pageScope = rememberCoroutineScope()
    val notificationEvents = remember(sharedStores.eventBus) {
        RaftNotificationPreferenceEvents(sharedStores.eventBus)
    }

    LaunchedEffect(environment.authStore) {
        session = environment.authStore.readSession()
    }
    LaunchedEffect(environment.notificationPreferenceRepository) {
        notificationPreferenceSnapshot =
            environment.notificationPreferenceRepository.getNotificationPreference()
    }
    DisposableEffect(notificationEvents) {
        val subscription =
            notificationEvents.addPreferenceListener { snapshot ->
                notificationPreferenceSnapshot = snapshot
                sharedStores
                    .sharedHomeStore(environment.storeScope)
                    ?.dispatch(SharedHomeIntent.RefreshNotifications)
            }
        onDispose { subscription.close() }
    }
    LaunchedEffect(environment.chatLayoutPreferenceRepository) {
        activitySenderAvatarsEnabled =
            environment.chatLayoutPreferenceRepository
                .getChatLayoutPreference()
                .activitySenderAvatarsEnabled
    }
    LaunchedEffect(route.page, route.itemId, route.launchIntent) {
        runSettingsNativeDetailLaunchSequence(
            route = route,
            loadPageContent = {
                settingsViewModel.accept(SharedSettingsIntent.LoadPageContent(route.page.storeDestination))
            },
            waitForAutoClose = { delay(it) },
            closePage = closePage,
        )
    }

    fun openNativePage(page: SettingsNativeDetailPage, itemId: String? = null) {
        if (!pager.openSettingsNativeDetailPage(page, environment.storeScope, itemId)) {
            bridge.logWarn("settings_native_detail_rejected page=${page.key}")
        }
    }

    SettingsNativeDetailPageContent(
        session = session,
        authDataSource = environment.authDataSource,
        settingsCapabilities = environment.settingsCapabilities,
        clearStorage = environment.dataSource::clearStorage,
        settingsState = settingsState,
        notificationPreferenceSnapshot = notificationPreferenceSnapshot,
        onSettingsIntent = settingsViewModel::dispatch,
        route = route,
        onBack = closePage,
        onOpenRouterPage = { jumpPage(pager, "router") },
        onOpenAdministrationPage = { pager.openSettingsAdministrationPage(environment.storeScope) },
        onOpenHandsFeedbackPage = { pager.openSettingsHandsFeedbackPage(environment.storeScope) },
        onOpenSourceLicensesPage = { openNativePage(SettingsNativeDetailPage.OpenSourceLicenses) },
        onOpenApiEnvironmentPage = { openNativePage(SettingsNativeDetailPage.ApiEnvironment) },
        onOpenDiagnosticsPage = { openNativePage(SettingsNativeDetailPage.Diagnostics) },
        onOpenLocalFeatureOverridesPage = { openNativePage(SettingsNativeDetailPage.LocalFeatureOverrides) },
        onOpenLocalFeatureOverridePage = { key ->
            openNativePage(SettingsNativeDetailPage.LocalFeatureOverride, key)
        },
        onMessageAlignmentSelected = {},
        onCompactConsecutiveMessagesSelected = {},
        onForegroundMessageBannersSelected = {},
        onActivityTaskStatusBadgesSelected = {},
        onConversationForwardGestureSelected = {},
        activitySenderAvatarsEnabled = activitySenderAvatarsEnabled,
        onActivitySenderAvatarsSelected = { enabled ->
            activitySenderAvatarsEnabled = enabled
            pageScope.launch {
                environment.chatLayoutPreferenceRepository.setActivitySenderAvatarsEnabled(enabled)
            }
        },
        onServerDrawerSelected = {},
        onHomeServerAvatarSelected = {},
        bottomContentPadding = raftBottomSafeAreaPadding() + RaftAppSpacing.Lg,
        timeContext = null,
        diagnosticsLogger = { message -> bridge.log("settings_native_detail $message") },
        serverPublicVisibilityRepository = environment.serverPublicVisibilityRepository,
        webBaseUrl = environment.webBaseUrl,
        onLogout = { pager.openLoginReplacingCurrentPage() },
    )
}

/** Row key of the Members entry at the top of the More (Settings) page. */
internal const val SettingsMoreMembersRowKey = "members"

/**
 * The Settings page as the phone More tab's root (stdrc / Jasper 2026-10-21): titled like the
 * tab ([title], 更多 / More / その他), Members and Computers lead as the first group, then the
 * Settings sections with their own headings; the rows named in [attentionRowKeys] wear the
 * attention dot the More tab shows ([RaftMoreAttention.settingsRowKey]).
 */
internal data class SettingsMoreRoot(
    val title: String,
    val membersTitle: String,
    val attentionRowKeys: Set<String> = emptySet(),
    /** False since D1a (raft-design #712): Members and Computers are on the server panel. */
    val leadsWithMembersAndComputers: Boolean = true,
)

/**
 * The Settings home rows for [moreRoot]: Members and Computers move to a first group (no section
 * heading) ahead of the existing sections, and attention rows get their dot. Without a More root
 * (the wide rail) the rows are unchanged.
 */
internal fun settingsHomeItemsForMoreRoot(
    items: List<SettingsHomePageLinkPayload>,
    moreRoot: SettingsMoreRoot?,
    membersSubtitle: String = "",
): List<SettingsHomePageLinkPayload> {
    if (moreRoot == null) return items
    if (!moreRoot.leadsWithMembersAndComputers) {
        return items.map { it.copy(attentionDot = it.key in moreRoot.attentionRowKeys) }
    }
    val computers = items.firstOrNull { it.key == SettingsDestinationComputers }
    val firstGroup =
        listOfNotNull(
            SettingsHomePageLinkPayload(
                key = SettingsMoreMembersRowKey,
                title = moreRoot.membersTitle,
                subtitle = membersSubtitle,
                iconName = RaftLucideIconName.Users,
            ),
            computers?.copy(section = null),
        )
    return (firstGroup + items.filter { it.key != SettingsDestinationComputers })
        .map { it.copy(attentionDot = it.key in moreRoot.attentionRowKeys) }
}

@Composable
private fun SettingsAppShellHomeContent(
    session: StoredAuthSession?,
    bottomContentPadding: Dp,
    onSettingsHeaderClick: () -> Unit,
    onSelect: (String) -> Unit,
    moreRoot: SettingsMoreRoot? = null,
    scrollToTopRequest: Int = 0,
    onBack: (() -> Unit)? = null,
) {
    val payload = appShellSettingsHomePayload(session)
    val membersSubtitle = stringResource(MR.strings.more_hub_members_subtitle)
    SettingsHomeContent(
        payload =
            payload.copy(
                title = moreRoot?.title ?: payload.title,
                items = settingsHomeItemsForMoreRoot(payload.items, moreRoot, membersSubtitle),
            ),
        bottomContentPadding = bottomContentPadding,
        onHeaderClick = onSettingsHeaderClick,
        onBack = onBack,
        onSelect = onSelect,
        scrollToTopRequest = scrollToTopRequest,
    )
}

@Composable
private fun SettingsNativeDetailPageContent(
    session: StoredAuthSession?,
    authDataSource: SharedAuthDataSource,
    settingsCapabilities: BridgeSettingsPlatformCapabilities,
    clearStorage: suspend (String) -> DataResult<SharedSettingsStorageSnapshot> = settingsCapabilities::clearStorage,
    settingsState: SharedSettingsState,
    notificationPreferenceSnapshot: NotificationPreferenceSnapshot,
    onSettingsIntent: (SharedSettingsIntent) -> Unit,
    route: SettingsNativeDetailRoute,
    onBack: () -> Unit,
    onOpenRouterPage: () -> Unit,
    onOpenAdministrationPage: () -> Unit,
    onOpenHandsFeedbackPage: () -> Unit,
    onOpenSourceLicensesPage: () -> Unit,
    onOpenApiEnvironmentPage: () -> Unit,
    onOpenDiagnosticsPage: () -> Unit,
    onOpenLocalFeatureOverridesPage: () -> Unit,
    onOpenLocalFeatureOverridePage: (String) -> Unit,
    onMessageAlignmentSelected: (MyMessageAlignmentPreference) -> Unit,
    onCompactConsecutiveMessagesSelected: (Boolean) -> Unit,
    onForegroundMessageBannersSelected: (Boolean) -> Unit,
    onActivityTaskStatusBadgesSelected: (Boolean) -> Unit,
    onConversationForwardGestureSelected: (Boolean) -> Unit,
    activitySenderAvatarsEnabled: Boolean,
    onActivitySenderAvatarsSelected: (Boolean) -> Unit,
    onServerDrawerSelected: (Boolean) -> Unit,
    onHomeServerAvatarSelected: (Boolean) -> Unit,
    bottomContentPadding: Dp,
    timeContext: RaftTimeContext?,
    diagnosticsLogger: (String) -> Unit = {},
    onSessionCleared: (StoredAuthSession) -> Unit = {},
    serverPublicVisibilityRepository: ServerPublicVisibilityRepository? = null,
    webBaseUrl: String = "",
    onLogout: () -> Unit
) {
    val diagnosticsSnapshot =
        (settingsState.diagnostics as? ScreenLoadState.Content<SharedSettingsDiagnosticsSnapshot>)?.data
    val localFeatureOverridesAvailable = diagnosticsSnapshot.localFeatureOverridesAvailable()
    val selectedLocalFeatureOverrideKey =
        route.itemId.takeIf { route.page == SettingsNativeDetailPage.LocalFeatureOverride }

    val localFeatureOverrideAvailabilityResolved =
        settingsState.diagnostics !is ScreenLoadState.Loading
    LaunchedEffect(
        route.page,
        route.itemId,
        localFeatureOverrideAvailabilityResolved,
        localFeatureOverridesAvailable,
    ) {
        if (
            shouldCloseLocalFeatureOverridePage(
                route = route,
                availabilityResolved = localFeatureOverrideAvailabilityResolved,
                available = localFeatureOverridesAvailable,
            )
        ) {
            onBack()
        }
    }

    LaunchedEffect(settingsState.effect) {
        val effect = settingsState.effect ?: return@LaunchedEffect
        when (effect) {
            SharedSettingsEffect.Logout -> {
                val clearedSession = session
                runCatchingPreservingCancellation { authDataSource.logout() }
                if (clearedSession != null) {
                    onSessionCleared(clearedSession)
                }
                onLogout()
            }
            is SharedSettingsEffect.ApiEnvironmentChanged -> {
                settingsCapabilities.bridgeToast(effect.message)
                val clearedSession = session
                runCatchingPreservingCancellation { authDataSource.logout() }
                if (clearedSession != null) {
                    onSessionCleared(clearedSession)
                }
                onLogout()
            }
            is SharedSettingsEffect.OpenUrl -> {
                settingsCapabilities.openExternalUrl(effect.url)
            }
            is SharedSettingsEffect.CopyText -> {
                settingsCapabilities.bridgeCopyToClipboard(effect.text)
            }
            SharedSettingsEffect.CopyDiagnostics -> {
                val ok = settingsCapabilities.copyDiagnostics()
                if (ok) {
                    onSettingsIntent(SharedSettingsIntent.Refresh)
                }
            }
            SharedSettingsEffect.ShareDiagnostics -> {
                settingsCapabilities.shareDiagnostics()
            }
            SharedSettingsEffect.ClearDiagnostics -> {
                val ok = settingsCapabilities.clearDiagnostics()
                if (ok) {
                    onSettingsIntent(SharedSettingsIntent.Refresh)
                }
            }
            SharedSettingsEffect.SendFeedback -> onOpenHandsFeedbackPage()
            SharedSettingsEffect.RequestNotificationPermission -> {
                val result = settingsCapabilities.requestNotificationPermission()
                onSettingsIntent(SharedSettingsIntent.CompleteSystemNotificationAction(MOBILE_ACTION_PERMISSION, result))
            }
            SharedSettingsEffect.OpenNotificationSettings -> {
                val result = settingsCapabilities.openNotificationSettings()
                onSettingsIntent(SharedSettingsIntent.CompleteSystemNotificationAction(MOBILE_ACTION_SETTINGS, result))
            }
            SharedSettingsEffect.SendTestNotification -> {
                val result = settingsCapabilities.sendTestNotification()
                onSettingsIntent(SharedSettingsIntent.CompleteSystemNotificationAction(MOBILE_ACTION_TEST_NOTIFICATION, result))
            }
            is SharedSettingsEffect.ClearStorage -> {
                val result = clearStorage(effect.target)
                when (result) {
                    is DataResult.Content -> {
                        onSettingsIntent(
                            SharedSettingsIntent.CompleteStorageClear(
                                effect.target,
                                ok = true,
                                snapshot = result.data
                            )
                        )
                    }
                    is DataResult.Empty -> {
                        onSettingsIntent(
                            SharedSettingsIntent.CompleteStorageClear(
                                effect.target,
                                ok = false,
                                code = result.reason.name,
                                emptyReason = result.reason
                            )
                        )
                    }
                    is DataResult.Error -> {
                        onSettingsIntent(
                            SharedSettingsIntent.CompleteStorageClear(
                                effect.target,
                                ok = false,
                                code = result.error.code,
                                screenError = result.error
                            )
                        )
                    }
                    is DataResult.NoPermission -> {
                        onSettingsIntent(
                            SharedSettingsIntent.CompleteStorageClear(
                                effect.target,
                                ok = false,
                                code = result.blocker.code,
                                permissionBlocker = result.blocker
                            )
                        )
                    }
                }
            }
            else -> Unit
        }
        onSettingsIntent(SharedSettingsIntent.ConsumeEffect)
    }

    var serverProfileName by remember { mutableStateOf("") }
    var languageRegionLanguageDraft by remember { mutableStateOf("") }
    var languageRegionDisplayDraft by remember { mutableStateOf("translated") }
    var languageRegionTimezoneDraft by remember { mutableStateOf("") }
    var languageRegionTimeFormatDraft by remember { mutableStateOf("") }
    var appearanceMessageFontSizeDraft by remember { mutableStateOf("md") }
    val currentServerSnapshot = settingsState.server.currentContent()
    val currentLanguageRegionSnapshot = settingsState.languageRegion.currentContent()
    val currentAppearanceSnapshot = settingsState.appearance.currentContent()
    val currentServerProfile = settingsState.server.currentContent()?.profile
    val currentServerName = currentServerProfile?.name ?: session?.currentServerSummary()?.name.orEmpty()
    LaunchedEffect(currentServerName) {
        serverProfileName = currentServerName
    }
    LaunchedEffect(
        currentLanguageRegionSnapshot?.browserLanguage?.selectedKey,
        currentLanguageRegionSnapshot?.translationDisplay?.selectedKey,
        currentLanguageRegionSnapshot?.timezone?.selectedKey,
        currentLanguageRegionSnapshot?.timeFormat?.selectedKey
    ) {
        currentLanguageRegionSnapshot?.let { snapshot ->
            languageRegionLanguageDraft = snapshot.browserLanguage.selectedKey
            languageRegionDisplayDraft = snapshot.translationDisplay.selectedKey
            languageRegionTimezoneDraft = snapshot.timezone.selectedKey
            languageRegionTimeFormatDraft = snapshot.timeFormat.selectedKey
        }
    }
    LaunchedEffect(currentAppearanceSnapshot?.messageBodyFontSize?.selectedKey) {
        currentAppearanceSnapshot?.let { snapshot ->
            appearanceMessageFontSizeDraft = snapshot.messageBodyFontSize.selectedKey
        }
    }

    SettingsDetailShell(
        title = settingsNativeDetailPageTitle(route),
        subtitle = "",
        iconName = settingsNativeDetailPageIcon(route.page),
        onBack = onBack,
        trailingContent = null
    ) {
        if (selectedLocalFeatureOverrideKey != null) {
            val selectedOverride =
                diagnosticsSnapshot
                    ?.registeredLocalFeatureOverrides()
                    ?.firstOrNull { it.key == selectedLocalFeatureOverrideKey }
            if (localFeatureOverridesAvailable && selectedOverride != null) {
                SharedSettingsLocalFeatureOverrideDetailContent(
                    flag = selectedOverride,
                    actionState = settingsState.actionState,
                    bottomContentPadding = bottomContentPadding,
                    onSetOverride = { key, mode ->
                        onSettingsIntent(SharedSettingsIntent.SetDiagnosticFeatureFlagOverride(key, mode))
                    },
                    onExportEvidence = { onSettingsIntent(SharedSettingsIntent.ShareDiagnostics) }
                )
            } else {
                SettingsSharedPlaceholder(
                    title = "Local Feature Overrides",
                    detail = "This internal-only feature override is unavailable in this build.",
                    iconName = RaftLucideIconName.SlidersHorizontal,
                    bottomContentPadding = bottomContentPadding
                )
            }
        } else when (route.page) {
            SettingsNativeDetailPage.LanguageRegion ->
                SettingsLanguageRegionContent(
                    state = settingsState.languageRegion,
                    mobileState = settingsState.mobile,
                    actionState = settingsState.actionState,
                    languageDraft = languageRegionLanguageDraft,
                    displayDraft = languageRegionDisplayDraft,
                    timezoneDraft = languageRegionTimezoneDraft,
                    timeFormatDraft = languageRegionTimeFormatDraft,
                    bottomContentPadding = bottomContentPadding,
                    onLanguageDraftChange = { languageRegionLanguageDraft = it },
                    onDisplayDraftChange = { languageRegionDisplayDraft = it },
                    onTimezoneDraftChange = { languageRegionTimezoneDraft = it },
                    onTimeFormatDraftChange = { languageRegionTimeFormatDraft = it },
                    onServerTranslationChange = { enabled ->
                        onSettingsIntent(SharedSettingsIntent.SetLanguageRegionServerTranslation(enabled))
                    },
                    onLocaleChange = { localeTag ->
                        onSettingsIntent(SharedSettingsIntent.SetLocale(localeTag))
                    },
                    onSaveLanguage = {
                        currentLanguageRegionSnapshot?.let { snapshot ->
                            val selectedMode = languageRegionDisplayDraft.ifBlank { snapshot.translationDisplay.selectedKey }
                            if (selectedMode != snapshot.translationDisplay.selectedKey) {
                                onSettingsIntent(SharedSettingsIntent.SetTranslationMode(selectedMode))
                            }
                            resolveSettingsTranslationTargetUpdate(
                                snapshot = snapshot,
                                languageDraft = languageRegionLanguageDraft,
                                displayDraft = languageRegionDisplayDraft
                            )?.let { language ->
                                onSettingsIntent(
                                    SharedSettingsIntent.SetTranslationTargetLanguage(language)
                                )
                            }
                        }
                    },
                    onSaveTime = {
                        val timezone = languageRegionTimezoneDraft.takeIf { it.isNotBlank() }
                        val timeFormat = languageRegionTimeFormatDraft.takeIf { it.isNotBlank() }
                        if (timezone != null || timeFormat != null) {
                            onSettingsIntent(
                                SharedSettingsIntent.UpdateLanguageRegionPreference(
                                    SettingsLanguageRegionPreferenceUpdateRequest(
                                        preferredTimezone = timezone,
                                        preferredTimeFormat = timeFormat
                                    )
                                )
                            )
                        }
                    },
                    onRetry = { onSettingsIntent(SharedSettingsIntent.Refresh) }
                )
            SettingsNativeDetailPage.Appearance ->
                SettingsAppearanceContent(
                    state = settingsState.appearance,
                    actionState = settingsState.actionState,
                    fontSizeDraft = appearanceMessageFontSizeDraft,
                    activitySenderAvatarsEnabled = activitySenderAvatarsEnabled,
                    bottomContentPadding = bottomContentPadding,
                    onFontSizeDraftChange = { appearanceMessageFontSizeDraft = it },
                    onActivitySenderAvatarsChange = onActivitySenderAvatarsSelected,
                    onSave = {
                        onSettingsIntent(
                            SharedSettingsIntent.UpdateAppearance(
                                SettingsAppearanceUpdateRequest(appearanceMessageFontSizeDraft)
                            )
                        )
                    },
                    onRetry = { onSettingsIntent(SharedSettingsIntent.Refresh) }
                )
            SettingsNativeDetailPage.Server -> {
                val currentServer = session?.currentServerSummary()
                val publicAccess =
                    rememberSettingsServerPublicAccessBinding(
                        repository = serverPublicVisibilityRepository,
                        serverId = currentServer?.id?.value,
                        role = currentServer?.role,
                        authDataSource = authDataSource,
                        webBaseUrl = webBaseUrl,
                        onCopyUrl = { url -> settingsCapabilities.bridgeCopyToClipboard(url) }
                    )
                SharedSettingsServerContent(
                    payload = settingsState.server.toServerPayload(
                        session = session,
                        refreshing = settingsState.isRefreshing(SharedSettingsDestination.Server),
                        actionState = settingsState.actionState,
                        timeContext = timeContext
                    ),
                    profileName = serverProfileName,
                    onProfileNameChange = { serverProfileName = it },
                    serverSnapshot = currentServerSnapshot,
                    serverRole = session?.currentServerSummary()?.role.orEmpty(),
                    actionState = settingsState.actionState,
                    bottomContentPadding = bottomContentPadding,
                    publicAccess = publicAccess,
                    webBaseUrl = webBaseUrl,
                ) { action, itemId ->
                    when (action) {
                        SERVER_ACTION_PROFILE_SAVE ->
                            itemId?.trim()?.takeIf { it.isNotBlank() }?.let {
                                onSettingsIntent(SharedSettingsIntent.UpdateServerProfile(SettingsServerProfileUpdateRequest(name = it)))
                            }
                        "openAdministration" -> onOpenAdministrationPage()
                        else -> Unit
                    }
                }
            }
            SettingsNativeDetailPage.Notifications ->
                SettingsNotificationsContent(
                    state = settingsState.mobile,
                    actionState = settingsState.actionState,
                    bottomContentPadding = bottomContentPadding,
                    notificationPreferenceSnapshot = notificationPreferenceSnapshot,
                    preferenceBusy =
                        settingsState.actionState?.inProgress == true &&
                            settingsState.actionState.action in
                            setOf(MOBILE_ACTION_NOTIFICATION_PREFERENCE, MOBILE_ACTION_SERVER_MUTE),
                    foregroundKeepAliveBusy =
                        settingsState.actionState?.inProgress == true &&
                            settingsState.actionState.action in
                            setOf(MOBILE_ACTION_FOREGROUND_KEEP_ALIVE, MOBILE_ACTION_SERVER_MUTE),
                    offlineComputerAlertsBusy =
                        settingsState.actionState?.inProgress == true &&
                            settingsState.actionState.action in
                            setOf(MOBILE_ACTION_OFFLINE_COMPUTER_ALERTS, MOBILE_ACTION_SERVER_MUTE),
                    foregroundMessageBannersBusy =
                        settingsState.actionState?.inProgress == true &&
                            settingsState.actionState.action in
                            setOf(MOBILE_ACTION_FOREGROUND_MESSAGE_BANNERS, MOBILE_ACTION_SERVER_MUTE),
                    onNotificationPreferenceChange = { enabled ->
                        onSettingsIntent(SharedSettingsIntent.SetNotificationPreference(enabled))
                        if (enabled) {
                            onSettingsIntent(SharedSettingsIntent.RequestNotificationPermission)
                        }
                    },
                    onForegroundKeepAlivePreferenceChange = { enabled ->
                        onSettingsIntent(SharedSettingsIntent.SetForegroundKeepAlivePreference(enabled))
                        if (enabled) {
                            onSettingsIntent(SharedSettingsIntent.RequestNotificationPermission)
                        }
                    },
                    onOfflineComputerAlertsChange = { enabled ->
                        onSettingsIntent(SharedSettingsIntent.SetOfflineComputerAlertsPreference(enabled))
                    },
                    onForegroundMessageBannersChange = { enabled ->
                        onSettingsIntent(SharedSettingsIntent.SetForegroundMessageBanners(enabled))
                        onForegroundMessageBannersSelected(enabled)
                    },
                    onServerNotificationModeChange = { mode ->
                        onSettingsIntent(SharedSettingsIntent.SetServerNotificationMode(mode))
                    },
                    onPushPreviewModeChange = { mode ->
                        onSettingsIntent(SharedSettingsIntent.SetPushPreviewMode(mode))
                    },
                    onPermission = { onSettingsIntent(SharedSettingsIntent.RequestNotificationPermission) },
                    onSettings = { onSettingsIntent(SharedSettingsIntent.OpenNotificationSettings) },
                    onTest = { onSettingsIntent(SharedSettingsIntent.SendTestNotification) },
                    onRetry = { onSettingsIntent(SharedSettingsIntent.Refresh) }
                )
            SettingsNativeDetailPage.Mobile ->
                SettingsMobileContent(
                    state = settingsState.mobile,
                    actionState = settingsState.actionState,
                    refreshing = settingsState.isRefreshing(SharedSettingsDestination.Mobile),
                    bottomContentPadding = bottomContentPadding,
                    onAlignmentChange = { itemId ->
                        onSettingsIntent(SharedSettingsIntent.SetMessageAlignment(itemId ?: "left"))
                        onMessageAlignmentSelected(MyMessageAlignmentPreference.fromStorageKey(itemId))
                    },
                    onLinkOpenModeChange = { itemId ->
                        onSettingsIntent(
                            SharedSettingsIntent.SetLinkOpenMode(
                                itemId ?: LinkOpenMode.Default.storageKey
                            )
                        )
                    },
                    onCompactConsecutiveMessagesChange = { enabled ->
                        onSettingsIntent(SharedSettingsIntent.SetCompactConsecutiveMessages(enabled))
                        onCompactConsecutiveMessagesSelected(enabled)
                    },
                    onLongMessageCollapseChange = { enabled ->
                        onSettingsIntent(SharedSettingsIntent.SetLongMessageCollapseEnabled(enabled))
                    },
                    onSingleTapOpensThreadChange = { enabled ->
                        onSettingsIntent(SharedSettingsIntent.SetSingleTapOpensThreadEnabled(enabled))
                    },
                    onNewMessageMenuChange = { enabled ->
                        onSettingsIntent(SharedSettingsIntent.SetNewMessageMenuEnabled(enabled))
                    },
                    onConversationForwardGestureChange = { enabled ->
                        onSettingsIntent(SharedSettingsIntent.SetConversationForwardGestureEnabled(enabled))
                        onConversationForwardGestureSelected(enabled)
                    },
                    onActivityTaskStatusBadgesChange = { enabled ->
                        onSettingsIntent(SharedSettingsIntent.SetActivityTaskStatusBadges(enabled))
                        onActivityTaskStatusBadgesSelected(enabled)
                    },
                    onComposerSendKeyChange = { enabled ->
                        onSettingsIntent(SharedSettingsIntent.SetComposerSendKey(enabled))
                    },
                    onMultiShellHostChange = { enabled ->
                        onSettingsIntent(SharedSettingsIntent.SetMultiShellHostEnabled(enabled))
                    },
                    onDesktopModeOnLargeScreenChange = { enabled ->
                        onSettingsIntent(SharedSettingsIntent.SetDesktopModeOnLargeScreen(enabled))
                    },
                    onServerDrawerChange = { enabled ->
                        onSettingsIntent(SharedSettingsIntent.SetServerDrawerEnabled(enabled))
                        onServerDrawerSelected(enabled)
                    },
                    onHomeServerAvatarChange = { enabled ->
                        onSettingsIntent(SharedSettingsIntent.SetHomeServerAvatarEnabled(enabled))
                        onHomeServerAvatarSelected(enabled)
                    },
                    onRealtimeCurlSocketIoChange = { enabled ->
                        onSettingsIntent(SharedSettingsIntent.SetRealtimeCurlSocketIoEnabled(enabled))
                    },
                    onHttp3Change = { enabled ->
                        onSettingsIntent(SharedSettingsIntent.SetHttp3Enabled(enabled))
                    },
                    onThreadReverseLayoutChange = { enabled ->
                        onSettingsIntent(SharedSettingsIntent.SetThreadReverseLayoutEnabled(enabled))
                    },
                    diagnosticsLogger = diagnosticsLogger,
                )
            SettingsNativeDetailPage.About ->
                SharedSettingsAboutContent(
                    state = settingsState.about,
                    fallback = appShellAboutFallback(session),
                    developerState = settingsState.developer,
                    updateCheck = settingsState.developer.currentContent()?.updateCheck,
                    actionState = settingsState.actionState,
                    bottomContentPadding = bottomContentPadding,
                    onCopyBuild = { summary ->
                        settingsCapabilities.bridgeCopyToClipboard(summary)
                    },
                    webUrl = sharedSettingsResolvedWebBaseUrl(settingsState.developer.configuredWebBaseUrlOrNull()),
                    onOpenRaft = { url -> settingsCapabilities.openUrl(url) },
                    onCheckHandsUpdate = {
                        onSettingsIntent(SharedSettingsIntent.CheckHandsUpdate)
                    },
                    onPrefetchReleaseNotes = { url ->
                        settingsCapabilities.prefetchReleaseNotes(url)
                    },
                    onOpenSourceLicenses = onOpenSourceLicensesPage,
                    onCopyEnvironmentInfo = { onSettingsIntent(SharedSettingsIntent.CopyDiagnostics) },
                    onOpenApiEnvironment = onOpenApiEnvironmentPage,
                    onOpenDiagnostics = onOpenDiagnosticsPage,
                )
            SettingsNativeDetailPage.OpenSourceLicenses ->
                SharedSettingsOpenSourceLicensesContent(
                    state = settingsState.openSourceLicenses,
                    bottomContentPadding = bottomContentPadding,
                    onOpenUrl = { url -> settingsCapabilities.openUrl(url) }
                )
            SettingsNativeDetailPage.Developer ->
                SharedSettingsDeveloperContent(
                    state = settingsState.developer,
                    actionState = settingsState.actionState,
                    bottomContentPadding = bottomContentPadding,
                    onOpenApiEnvironment = onOpenApiEnvironmentPage,
                    onOpenDiagnostics = onOpenDiagnosticsPage,
                    onOpenRouter = onOpenRouterPage,
                )
            SettingsNativeDetailPage.ApiEnvironment ->
                SharedSettingsApiEnvironmentContent(
                    state = settingsState.developer,
                    actionState = settingsState.actionState,
                    bottomContentPadding = bottomContentPadding,
                    onSaveApiEnvironment = { request ->
                        onSettingsIntent(SharedSettingsIntent.SaveApiEnvironment(request))
                    }
                )
            SettingsNativeDetailPage.Diagnostics ->
                SharedSettingsDiagnosticsContent(
                    state = settingsState.diagnostics,
                    actionState = settingsState.actionState,
                    bottomContentPadding = bottomContentPadding,
                    onCopyValue = { value -> settingsCapabilities.bridgeCopyToClipboard(value) },
                    onCopyLogs = { onSettingsIntent(SharedSettingsIntent.CopyDiagnostics) },
                    onShareLogs = { onSettingsIntent(SharedSettingsIntent.ShareDiagnostics) },
                    onSetDiagnosticFeatureFlagOverride = { key, mode ->
                        onSettingsIntent(SharedSettingsIntent.SetDiagnosticFeatureFlagOverride(key, mode))
                    },
                    onOpenLocalFeatureOverrides = {
                        if (localFeatureOverridesAvailable) {
                            onOpenLocalFeatureOverridesPage()
                        }
                    },
                    onSendFeedback = { onSettingsIntent(SharedSettingsIntent.SendFeedback) }
                )
            SettingsNativeDetailPage.LocalFeatureOverrides ->
                if (localFeatureOverridesAvailable && diagnosticsSnapshot != null) {
                    SharedSettingsLocalFeatureOverridesContent(
                        snapshot = diagnosticsSnapshot,
                        bottomContentPadding = bottomContentPadding,
                        onOpenOverride = onOpenLocalFeatureOverridePage,
                    )
                } else {
                    SettingsSharedPlaceholder(
                        title = "Local Feature Overrides",
                        detail = "This internal-only feature override page is unavailable in this build.",
                        iconName = RaftLucideIconName.SlidersHorizontal,
                        bottomContentPadding = bottomContentPadding
                    )
                }
            SettingsNativeDetailPage.LocalFeatureOverride -> Unit
        }
    }
}

@Composable
private fun SharedSettingsSectionContent(
    payload: RaftSharedSettingsPayload,
    bottomContentPadding: Dp = RaftAppSpacing.Lg,
    onCopyValue: ((String) -> Unit)? = null,
    onAction: (String, String?) -> Unit
) {
    LazyColumn(
        modifier = Modifier.fillMaxSize().background(RaftColor.Canvas).padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(12.dp)
    ) {
        payload.sections.forEach { section ->
            item { SharedSettingsSectionCard(section, onCopyValue, onAction) }
        }
        item { Spacer(Modifier.height(bottomContentPadding)) }
    }
}

@Composable
private fun rememberSettingsServerPublicAccessBinding(
    repository: ServerPublicVisibilityRepository?,
    serverId: String?,
    role: String?,
    authDataSource: SharedAuthDataSource,
    webBaseUrl: String,
    onCopyUrl: (String) -> Unit,
): SettingsServerPublicAccessBinding? {
    if (repository == null) return null
    val scope = rememberCoroutineScope()
    val store =
        remember(repository, scope, authDataSource) {
            ServerPublicVisibilityStore(
                repository = repository,
                scope = scope,
                refreshServerList = { authDataSource.loadServers() }
            )
        }
    LaunchedEffect(store, serverId, role) {
        store.dispatch(ServerPublicVisibilityIntent.Start(serverId = serverId, role = role))
    }
    val state by store.state.collectAsState()
    return SettingsServerPublicAccessBinding(
        state = state,
        webBaseUrl = webBaseUrl,
        onIntent = store::dispatch,
        onCopyUrl = onCopyUrl,
    )
}

internal data class SettingsServerPublicAccessBinding(
    val state: ServerPublicVisibilityState,
    val webBaseUrl: String,
    val onIntent: (ServerPublicVisibilityIntent) -> Unit,
    val onCopyUrl: (String) -> Unit,
)

@Composable
private fun SharedSettingsServerContent(
    payload: RaftSharedSettingsPayload,
    profileName: String,
    onProfileNameChange: (String) -> Unit,
    serverSnapshot: SettingsServerSnapshot?,
    serverRole: String,
    actionState: build.raft.app.data.SharedSettingsActionState?,
    bottomContentPadding: Dp = RaftAppSpacing.Lg,
    joinLinkMaxUses: String = "",
    onJoinLinkMaxUsesChange: (String) -> Unit = {},
    joinLinkExpiresAt: String = "",
    onJoinLinkExpiresAtChange: (String) -> Unit = {},
    agreementEnabled: Boolean = false,
    onAgreementEnabledChange: (Boolean) -> Unit = {},
    agreementTitle: TextFieldValue = TextFieldValue(""),
    onAgreementTitleChange: (TextFieldValue) -> Unit = {},
    agreementBody: TextFieldValue = TextFieldValue(""),
    onAgreementBodyChange: (TextFieldValue) -> Unit = {},
    hideHumansFromMembers: Boolean = false,
    onHideHumansFromMembersChange: (Boolean) -> Unit = {},
    onboardingAgentId: String = "",
    onOnboardingAgentIdChange: (String) -> Unit = {},
    onboardingGreetingEnabled: Boolean = true,
    onOnboardingGreetingEnabledChange: (Boolean) -> Unit = {},
    timeContext: RaftTimeContext? = null,
    expectedServerSlug: String = "",
    deleteConfirmationName: String = "",
    onDeleteConfirmationNameChange: (String) -> Unit = {},
    showProfileCard: Boolean = true,
    onCreateJoinLink: (SettingsServerJoinLinkCreateRequest) -> Unit = {},
    /** Owner "Public access" section; null on surfaces that do not host it (Administration, fixtures). */
    publicAccess: SettingsServerPublicAccessBinding? = null,
    /** The active Developer environment web URL; a relative join link copies against it. */
    webBaseUrl: String = "",
    onAction: (String, String?) -> Unit
) {
    val visualFullHeight = settingsVisualFullHeightEnabled()
    LazyColumn(
        modifier = Modifier.fillMaxSize().background(RaftColor.Canvas).padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(12.dp)
    ) {
        if (showProfileCard) {
            item {
                SettingsServerProfileFormCard(
                    profile = serverSnapshot?.profile,
                    draftName = profileName,
                    fallbackName = payload.heroLabel,
                    fallbackSlug = expectedServerSlug,
                    role = serverRole,
                    actionState = actionState,
                    onNameChange = onProfileNameChange,
                    onSubmit = { onAction(SERVER_ACTION_PROFILE_SAVE, profileName.trim()) }
                )
            }
        }
        // Web ServerTabContent order: Profile, then Public access.
        if (publicAccess != null && publicAccess.state.sectionVisible) {
            item {
                SettingsServerPublicAccessCard(
                    state = publicAccess.state,
                    webBaseUrl = publicAccess.webBaseUrl,
                    onIntent = publicAccess.onIntent,
                    onCopyUrl = publicAccess.onCopyUrl
                )
            }
        }
        payload.sections.forEach { section ->
            when (section.title) {
                "Profile", "Danger Zone" -> Unit
                "Admins" ->
                    item {
                        SettingsServerAdminsCard(
                            members = serverSnapshot?.admins.orEmpty(),
                            section = serverSnapshot?.sections?.firstOrNull { it.key == "admins" },
                            actorRole = serverRole,
                            actionState = actionState,
                            onAction = onAction
                        )
                    }
                "Pending Invites" ->
                    item {
                        SettingsServerInvitesCard(
                            invites = serverSnapshot?.pendingInvites.orEmpty(),
                            section = serverSnapshot?.sections?.firstOrNull { it.key == "pending_invites" },
                            actionState = actionState,
                            timeContext = timeContext,
                            onAction = onAction
                        )
                    }
                "Join Links" ->
                    item {
                        SettingsServerJoinLinksCard(
                            links = serverSnapshot?.joinLinks.orEmpty(),
                            section = serverSnapshot?.sections?.firstOrNull { it.key == "join_links" },
                            maxUses = joinLinkMaxUses,
                            expiresAt = joinLinkExpiresAt,
                            actionState = actionState,
                            timeContext = timeContext,
                            onMaxUsesChange = onJoinLinkMaxUsesChange,
                            onExpiresAtChange = onJoinLinkExpiresAtChange,
                            onCreate = onCreateJoinLink,
                            webBaseUrl = webBaseUrl,
                            onAction = onAction
                        )
                    }
                "Pre-join Agreement" ->
                    item {
                        SettingsServerAgreementCard(
                            agreement = serverSnapshot?.agreement,
                            section = serverSnapshot?.sections?.firstOrNull { it.key == "pre_join_agreement" },
                            enabled = agreementEnabled,
                            title = agreementTitle,
                            bodyMarkdown = agreementBody,
                            actionState = actionState,
                            onEnabledChange = onAgreementEnabledChange,
                            onTitleChange = onAgreementTitleChange,
                            onBodyChange = onAgreementBodyChange,
                            onSubmit = { onAction(SERVER_ACTION_AGREEMENT_SAVE, null) }
                        )
                    }
                "Onboarding" ->
                    item {
                        SettingsServerOnboardingCard(
                            onboarding = serverSnapshot?.onboarding,
                            section = serverSnapshot?.sections?.firstOrNull { it.key == "onboarding_agent" },
                            selectedAgentId = onboardingAgentId,
                            greetingEnabled = onboardingGreetingEnabled,
                            actionState = actionState,
                            onAgentSelected = onOnboardingAgentIdChange,
                            onGreetingEnabledChange = onOnboardingGreetingEnabledChange,
                            onSubmit = { onAction(SERVER_ACTION_ONBOARDING_SAVE, null) }
                        )
                    }
                "Member Permissions" ->
                    item {
                        SettingsServerMemberPermissionsCard(
                            profile = serverSnapshot?.profile,
                            section = serverSnapshot?.sections?.firstOrNull { it.key == "member_permissions" },
                            hideHumansFromMembers = hideHumansFromMembers,
                            actionState = actionState,
                            onHideHumansFromMembersChange = onHideHumansFromMembersChange,
                            onSubmit = { onAction(SERVER_ACTION_MEMBER_PERMISSIONS_SAVE, null) }
                        )
                    }
                else -> item { SharedSettingsSectionCard(section, onAction = onAction) }
            }
        }
        item {
            SettingsServerDangerZoneCard(
                serverName = serverSnapshot?.profile?.name ?: payload.heroLabel,
                expectedServerSlug = expectedServerSlug,
                role = serverRole,
                dangerSection = serverSnapshot?.sections?.firstOrNull { it.key == "danger" },
                confirmationSlug = deleteConfirmationName,
                actionState = actionState,
                onConfirmationSlugChange = onDeleteConfirmationNameChange,
                onLeave = { onAction(SERVER_ACTION_LEAVE, null) },
                onDelete = { onAction(SERVER_ACTION_DELETE, deleteConfirmationName.trim()) }
            )
        }
        item { Spacer(Modifier.height(bottomContentPadding)) }
        if (visualFullHeight) {
            item { SettingsVisualFullHeightSentinel() }
        }
    }
}

