@Composable
private fun SettingsConnectedAppsContentContent(
    modifier: Modifier = Modifier,
    data: SettingsConnectedAppsContentData,
    callbacks: SettingsConnectedAppsContentCallbacks,
) {
    val state = data.state
    val selectedTab = data.selectedTab
    val onSelectedTabChange = callbacks.onSelectedTabChange
    val editingId = data.editingId
    val name = data.name
    val clientId = data.clientId
    val description = data.description
    val homepageUrl = data.homepageUrl
    val returnUrl = data.returnUrl
    val manifestUrl = data.manifestUrl
    val publishCategory = data.publishCategory
    val publishDataAccess = data.publishDataAccess
    val marketplaceSearch = data.marketplaceSearch
    val marketplaceCategory = data.marketplaceCategory
    val selectedMarketplaceId = data.selectedMarketplaceId
    val selectedBuiltInId = data.selectedBuiltInId
    val confirmTarget = data.confirmTarget
    val actionState = data.actionState
    val bottomContentPadding = data.bottomContentPadding
    val onNameChange = callbacks.onNameChange
    val onClientIdChange = callbacks.onClientIdChange
    val onDescriptionChange = callbacks.onDescriptionChange
    val onHomepageUrlChange = callbacks.onHomepageUrlChange
    val onReturnUrlChange = callbacks.onReturnUrlChange
    val onManifestUrlChange = callbacks.onManifestUrlChange
    val onPublishCategoryChange = callbacks.onPublishCategoryChange
    val onPublishDataAccessChange = callbacks.onPublishDataAccessChange
    val onMarketplaceSearchChange = callbacks.onMarketplaceSearchChange
    val onMarketplaceCategoryChange = callbacks.onMarketplaceCategoryChange
    val onOpenMarketplaceDetail = callbacks.onOpenMarketplaceDetail
    val onDismissMarketplaceDetail = callbacks.onDismissMarketplaceDetail
    val onOpenBuiltInDetail = callbacks.onOpenBuiltInDetail
    val onDismissBuiltInDetail = callbacks.onDismissBuiltInDetail
    val onStartEdit = callbacks.onStartEdit
    val onCancelEdit = callbacks.onCancelEdit
    val onRegister = callbacks.onRegister
    val onUpdate = callbacks.onUpdate
    val onUploadLogo = callbacks.onUploadLogo
    val onClearLogo = callbacks.onClearLogo
    val onRequestDelete = callbacks.onRequestDelete
    val onConfirmDelete = callbacks.onConfirmDelete
    val onPublish = callbacks.onPublish
    val onInstall = callbacks.onInstall
    val onRequestUninstall = callbacks.onRequestUninstall
    val onConfirmUninstall = callbacks.onConfirmUninstall
    val onDismissConfirm = callbacks.onDismissConfirm
    val onCopySecret = callbacks.onCopySecret
    val onOpenUrl = callbacks.onOpenUrl
    val onRefresh = callbacks.onRefresh
    val snapshot = state.currentContent()
    val selectedMarketplace = snapshot?.marketplace?.firstOrNull { it.id == selectedMarketplaceId }
    val selectedBuiltIn = snapshot?.builtIn?.firstOrNull { it.id == selectedBuiltInId }
    selectedMarketplace?.let { app ->
        SettingsConnectedAppMarketplaceDetailDialog(
            app = app,
            actionState = actionState,
            onDismiss = onDismissMarketplaceDetail,
            onInstall = onInstall,
            onRequestUninstall = onRequestUninstall,
            onOpenUrl = onOpenUrl
        )
    }
    selectedBuiltIn?.let { app ->
        SettingsConnectedAppBuiltInDetailDialog(
            app = app,
            onDismiss = onDismissBuiltInDetail,
            onOpenUrl = onOpenUrl
        )
    }
    confirmTarget?.let { target ->
        SettingsConnectedAppsConfirmDialog(
            target = target,
            snapshot = snapshot,
            actionState = actionState,
            onDismiss = onDismissConfirm,
            onConfirmDelete = onConfirmDelete,
            onConfirmUninstall = onConfirmUninstall
        )
    }
    val visualFullHeight = settingsVisualFullHeightEnabled()
    LazyColumn(
        modifier = Modifier.fillMaxSize().background(RaftColor.Canvas).padding(16.dp),
        verticalArrangement = Arrangement.spacedBy(12.dp)
    ) {
        when (state) {
            ScreenLoadState.Loading ->
                item {
                    SettingsFormSectionCard(iconName = RaftLucideIconName.LoaderCircle, title = stringResource(MR.strings.common_loading)) {
                        SettingsFormDetailText(stringResource(MR.strings.settings_connected_apps_loading))
                    }
                }
            is ScreenLoadState.Empty ->
                item {
                    SettingsFormSectionCard(iconName = RaftLucideIconName.Blocks, title = stringResource(MR.strings.settings_connected_apps_empty)) {
                        SettingsFormEmptyText(stringResource(MR.strings.settings_connected_apps_unavailable))
                        RaftBrutalActionButton(
                            label = stringResource(MR.strings.common_retry),
                            onClick = onRefresh,
                            leadingIcon = RaftLucideIconName.RefreshCw,
                            backgroundColor = RaftColor.SurfaceWhite
                        )
                    }
                }
            is ScreenLoadState.Error ->
                item {
                    SettingsFormSectionCard(iconName = RaftLucideIconName.TriangleAlert, title = stringResource(MR.strings.settings_connected_apps_error)) {
                        SettingsFormErrorText(state.error.localizedUserFacingMessage())
                        RaftBrutalActionButton(
                            label = stringResource(MR.strings.common_retry),
                            onClick = onRefresh,
                            leadingIcon = RaftLucideIconName.RefreshCw,
                            backgroundColor = RaftColor.SurfaceWhite
                        )
                    }
                }
            is ScreenLoadState.NoPermission ->
                item {
                    SettingsFormSectionCard(iconName = RaftLucideIconName.Lock, title = stringResource(MR.strings.settings_connected_apps_permission_required)) {
                        SettingsFormErrorText(settingsConnectedAppsPermissionCopy(state.blocker, stringResource(MR.strings.settings_connected_apps_permission_admin)))
                    }
                }
            is ScreenLoadState.Content -> {
                item {
                    SettingsConnectedAppsOverviewCard(
                        snapshot = snapshot,
                        loading = false,
                        onRegister = { onSelectedTabChange("myapps") }
                    )
                }
                item {
                    SettingsConnectedAppsTabControl(
                        selectedValue = selectedTab,
                        snapshot = snapshot,
                        onValueSelected = onSelectedTabChange
                    )
                }
                snapshot?.oneTimeClientSecret?.let { secret ->
                    item {
                        SettingsConnectedAppSecretCard(
                            secret = secret,
                            onCopySecret = onCopySecret
                        )
                    }
                }
                when (selectedTab) {
                    "installed" ->
                        item {
                            SettingsConnectedAppsInstalledCard(
                                installed = snapshot?.installed.orEmpty(),
                                clients = snapshot?.registered.orEmpty(),
                                actionState = actionState,
                                onStartEdit = onStartEdit,
                                onRequestUninstall = onRequestUninstall
                            )
                        }
                    "myapps" -> {
                        item {
                            SettingsConnectedAppEditorCard(
                                snapshot = snapshot,
                                editingId = editingId,
                                name = name,
                                clientId = clientId,
                                description = description,
                                homepageUrl = homepageUrl,
                                returnUrl = returnUrl,
                                manifestUrl = manifestUrl,
                                publishCategory = publishCategory,
                                publishDataAccess = publishDataAccess,
                                actionState = actionState,
                                onNameChange = onNameChange,
                                onClientIdChange = onClientIdChange,
                                onDescriptionChange = onDescriptionChange,
                                onHomepageUrlChange = onHomepageUrlChange,
                                onReturnUrlChange = onReturnUrlChange,
                                onManifestUrlChange = onManifestUrlChange,
                                onPublishCategoryChange = onPublishCategoryChange,
                                onPublishDataAccessChange = onPublishDataAccessChange,
                                onCancelEdit = onCancelEdit,
                                onRegister = onRegister,
                                onUpdate = onUpdate,
                                onUploadLogo = onUploadLogo,
                                onClearLogo = onClearLogo
                            )
                        }
                        item {
                            SettingsConnectedAppClientsCard(
                                clients = snapshot?.registered.orEmpty(),
                                actionState = actionState,
                                onStartEdit = onStartEdit,
                                onRequestDelete = onRequestDelete,
                                onPublish = onPublish,
                                publishCategory = publishCategory,
                                publishDataAccess = publishDataAccess
                            )
                        }
                    }
                    else -> {
                        item {
                            SettingsConnectedAppsBuiltInBand(
                                apps = snapshot?.builtIn.orEmpty(),
                                onOpenDetail = onOpenBuiltInDetail
                            )
                        }
                        item {
                            SettingsConnectedAppsMarketplaceCard(
                                marketplace = snapshot?.marketplace.orEmpty(),
                                search = marketplaceSearch,
                                category = marketplaceCategory,
                                actionState = actionState,
                                onSearchChange = onMarketplaceSearchChange,
                                onCategoryChange = onMarketplaceCategoryChange,
                                onOpenDetail = onOpenMarketplaceDetail
                            )
                        }
                    }
                }
            }
        }
        item { Spacer(Modifier.height(bottomContentPadding)) }
        if (visualFullHeight) {
            item { SettingsVisualFullHeightSentinel() }
        }
    }
}

@Composable
private fun SettingsConnectedAppsOverviewCard(
    snapshot: SettingsConnectedAppsSnapshot?,
    loading: Boolean,
    onRegister: () -> Unit
) {
    SettingsFormSectionCard(iconName = RaftLucideIconName.Link2, title = stringResource(MR.strings.settings_connected_apps_title)) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(12.dp),
            verticalAlignment = Alignment.Top
        ) {
            Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(5.dp)) {
                Text(
                    stringResource(MR.strings.settings_connected_apps_overview_title),
                    style = RaftType.Button.copy(color = RaftColor.TextBlack),
                    color = RaftColor.TextBlack
                )
                Text(
                    stringResource(MR.strings.settings_connected_apps_overview_detail),
                    style = RaftType.Caption.copy(color = RaftColor.TextMutedGray),
                    color = RaftColor.TextMutedGray
                )
                Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) {
                    SettingsConnectedAppsBadge(stringResource(MR.strings.settings_connected_apps_badge_experimental), RaftColor.BrandYellow)
                    if (loading) SettingsConnectedAppsBadge(stringResource(MR.strings.settings_connected_apps_badge_loading), RaftColor.EmptyStateGray)
                }
            }
            RaftBrutalActionButton(
                label = stringResource(MR.strings.settings_connected_apps_action_register),
                onClick = onRegister,
                leadingIcon = RaftLucideIconName.Plus,
                backgroundColor = RaftColor.AccentPink,
                minWidth = 118.dp
            )
        }
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.spacedBy(8.dp)
        ) {
            SettingsConnectedAppsMetric(stringResource(MR.strings.settings_connected_apps_metric_marketplace), (snapshot?.builtIn.orEmpty().size + snapshot?.marketplace.orEmpty().size).toString(), Modifier.weight(1f))
            SettingsConnectedAppsMetric(stringResource(MR.strings.settings_connected_apps_metric_installed), snapshot?.installed.orEmpty().size.toString(), Modifier.weight(1f))
            SettingsConnectedAppsMetric(stringResource(MR.strings.settings_connected_apps_metric_my_apps), snapshot?.registered.orEmpty().size.toString(), Modifier.weight(1f))
        }
    }
}

