/**
 * What a long press on a join link copies: an absolute link as it is; a relative one against
 * the active Developer environment [webBaseUrl] (the invite dialog's normaliser). Null with no
 * environment URL to resolve it, so a relative link never copies against a hardcoded host.
 */
internal fun settingsServerJoinLinkCopyUrl(rawUrl: String?, webBaseUrl: String): String? {
    val trimmed = rawUrl?.trim().orEmpty()
    return when {
        trimmed.isBlank() -> null
        trimmed.startsWith("http://") || trimmed.startsWith("https://") -> trimmed
        webBaseUrl.isBlank() -> null
        else -> normalizeInviteHumanJoinUrl(trimmed, webBaseUrl)
    }
}

@Composable
private fun SettingsServerJoinLinksCard(
    links: List<SettingsServerJoinLinkSnapshot>,
    section: SettingsServerSectionSnapshot?,
    maxUses: String,
    expiresAt: String,
    actionState: build.raft.app.data.SharedSettingsActionState?,
    timeContext: RaftTimeContext?,
    onMaxUsesChange: (String) -> Unit,
    onExpiresAtChange: (String) -> Unit,
    onCreate: (SettingsServerJoinLinkCreateRequest) -> Unit,
    webBaseUrl: String = "",
    onAction: (String, String?) -> Unit
) {
    val trimmedMaxUses = maxUses.trim()
    val parsedMaxUses = trimmedMaxUses.takeIf { it.isNotBlank() }?.toIntOrNull()
    val maxUsesInvalid = trimmedMaxUses.isNotBlank() && (parsedMaxUses == null || parsedMaxUses <= 0)
    val createBusy = actionState?.action == SERVER_ACTION_JOIN_LINK_CREATE && actionState.inProgress
    val createEnabled = !createBusy && !maxUsesInvalid
    SettingsFormSectionCard(iconName = RaftLucideIconName.Link2, title = stringResource(MR.strings.settings_section_join_links_title)) {
        section.localizedDetail()?.takeIf { it.isNotBlank() }?.let { SettingsFormDetailText(it) }
        RaftBrutalTextField(
            label = stringResource(MR.strings.settings_server_label_max_uses),
            labelSize = RaftFormFieldSize.Compact,
            value = maxUses,
            placeholder = stringResource(MR.strings.settings_server_placeholder_unlimited),
            onValueChange = onMaxUsesChange,
            optional = true,
            enabled = !createBusy
        )
        RaftBrutalTextField(
            label = stringResource(MR.strings.settings_server_label_expires_at),
            labelSize = RaftFormFieldSize.Compact,
            value = expiresAt,
            placeholder = "2026-06-01T09:00:00Z",
            onValueChange = onExpiresAtChange,
            optional = true,
            enabled = !createBusy
        )
        if (maxUsesInvalid) {
            SettingsFormErrorText(stringResource(MR.strings.settings_server_error_max_uses))
        }
        RaftButton(
            text = actionState.serverLocalizedStatusFor(SERVER_ACTION_JOIN_LINK_CREATE, stringResource(MR.strings.settings_server_action_create_join_link)),
            onClick = {
                onCreate(
                    SettingsServerJoinLinkCreateRequest(
                        expiresAt = expiresAt.trim().ifBlank { null },
                        maxUses = parsedMaxUses?.takeIf { it > 0 }
                    )
                )
            },
            enabled = createEnabled,
            leadingIcon = { RaftSlotIcon(RaftLucideIconName.Plus) },
            variant = RaftButtonVariant.Primary,
            size = RaftButtonSize.Lg
        )
        SettingsFormDivider()
        if (links.isEmpty()) {
            SettingsFormEmptyText(stringResource(MR.strings.settings_admin_no_join_links))
        } else {
            links.forEach { link ->
                SettingsServerActionRow(
                    title = link.url ?: link.label,
                    copyText = settingsServerJoinLinkCopyUrl(link.url, webBaseUrl),
                    detail =
                        listOfNotNull(
                            link.maxUsesLabel,
                            link.usageLabel,
                            relativeSettingsTimestampLabel(link.expiresAtLabel, timeContext)
                        ).joinToString(" · "),
                    buttonLabel = actionState.serverLocalizedStatusFor(SERVER_ACTION_JOIN_LINK_REVOKE, stringResource(MR.strings.settings_server_action_revoke), link.id),
                    buttonIcon = RaftLucideIconName.Unlink,
                    buttonColor = RaftColor.SurfaceWhite,
                    enabled = actionState?.inProgress != true,
                    onClick = { onAction(SERVER_ACTION_JOIN_LINK_REVOKE, link.id) }
                )
            }
        }
        if (actionState?.action == SERVER_ACTION_JOIN_LINK_REVOKE && actionState.errorCode != null) {
            SettingsFormErrorText(actionState)
        }
    }
}

@Composable
private fun SettingsServerAgreementCard(
    agreement: SettingsServerAgreementSnapshot?,
    section: SettingsServerSectionSnapshot?,
    enabled: Boolean,
    title: TextFieldValue,
    bodyMarkdown: TextFieldValue,
    actionState: build.raft.app.data.SharedSettingsActionState?,
    onEnabledChange: (Boolean) -> Unit,
    onTitleChange: (TextFieldValue) -> Unit,
    onBodyChange: (TextFieldValue) -> Unit,
    onSubmit: () -> Unit
) {
    val canSave = agreement?.canSave == true
    val busy = actionState?.action == SERVER_ACTION_AGREEMENT_SAVE && actionState.inProgress
    val bodyTooLong = bodyMarkdown.text.length > PRE_JOIN_AGREEMENT_BODY_MAX_LENGTH
    val titleTooLong = title.text.length > PRE_JOIN_AGREEMENT_TITLE_VALIDATION_MAX_LENGTH
    val dirty =
        agreement != null &&
            (enabled != agreement.enabled || title.text.trim() != agreement.title || bodyMarkdown.text != agreement.bodyMarkdown)
    val saveEnabled = canSave && dirty && !busy && !bodyTooLong && !titleTooLong
    SettingsFormSectionCard(iconName = RaftLucideIconName.FileCheck, title = stringResource(MR.strings.settings_section_pre_join_agreement_title)) {
        section.localizedDetail()?.takeIf { it.isNotBlank() }?.let { SettingsFormDetailText(it) }
        SettingsSegmentedControlField(
            selectedValue = if (enabled) "enabled" else "disabled",
            options = listOf(
                SegmentedControlOption("enabled", stringResource(MR.strings.settings_server_agreement_required), RaftLucideIconName.CircleCheck),
                SegmentedControlOption("disabled", stringResource(MR.strings.settings_server_agreement_disabled), RaftLucideIconName.X)
            ),
            onValueSelected = { onEnabledChange(it == "enabled") },
            enabled = canSave && !busy
        )
        RaftBrutalTextField(
            label = stringResource(MR.strings.settings_server_label_title),
            labelSize = RaftFormFieldSize.Compact,
            value = title,
            placeholder = stringResource(MR.strings.settings_server_placeholder_agreement_title),
            onValueChange = { onTitleChange(it.coerceTextLength(PRE_JOIN_AGREEMENT_TITLE_INPUT_MAX_LENGTH)) },
            required = enabled,
            enabled = canSave && !busy
        )
        RaftBrutalTextField(
            label = stringResource(MR.strings.settings_server_label_body_markdown),
            labelSize = RaftFormFieldSize.Compact,
            value = bodyMarkdown,
            placeholder = stringResource(MR.strings.settings_server_placeholder_agreement_body),
            onValueChange = onBodyChange,
            required = enabled,
            enabled = canSave && !busy,
            maxLines = 7,
            fieldMinHeight = 142.dp
        )
        SettingsFormDetailText("${bodyMarkdown.text.length} / $PRE_JOIN_AGREEMENT_BODY_MAX_LENGTH characters")
        if (titleTooLong) {
            SettingsFormErrorText(stringResource(MR.strings.settings_server_error_agreement_title))
        }
        if (bodyTooLong) {
            SettingsFormErrorText(stringResource(MR.strings.settings_server_error_agreement_body))
        }
        SettingsAgreementPreview(bodyMarkdown)
        if (actionState?.action == SERVER_ACTION_AGREEMENT_SAVE && actionState.errorCode != null) {
            SettingsFormErrorText(actionState)
        }
        if (canSave) {
            RaftButton(
                text = actionState.serverLocalizedStatusFor(SERVER_ACTION_AGREEMENT_SAVE, stringResource(MR.strings.settings_server_action_save_agreement)),
                onClick = onSubmit,
                enabled = saveEnabled,
                leadingIcon = { RaftSlotIcon(RaftLucideIconName.Save) },
                variant = RaftButtonVariant.Primary,
                size = RaftButtonSize.Lg
            )
        }
    }
}

