@Composable
private fun SharedSettingsRow(
    row: RaftSharedSettingsRow,
    showDivider: Boolean,
    onCopyValue: ((String) -> Unit)? = null,
    onAction: (String, String?) -> Unit
) {
    Column(modifier = Modifier.fillMaxWidth()) {
        if (showDivider) {
            Box(Modifier.fillMaxWidth().height(RaftAppStroke.Thin).background(RaftColor.BorderHairline))
        }
        // A row's copyValue copies on a long press on every settings page: the page's own
        // handler when it passes one, else the design-system copy (host pasteboard + "Copied").
        val copyAction = onCopyValue ?: rememberRaftCopyAction()
        val haptics = LocalHapticFeedback.current
        val copyable = row.copyValue.isNotBlank()
        val gestureOwner =
            rememberRaftGestureOwner(
                surface = "settings-row",
                semanticIdentity = row.key,
                callbacks =
                    SharedSettingsRowGestureCallbacks(
                        row = row,
                        onCopyValue = { value ->
                            haptics.performHapticFeedback(HapticFeedbackType.LongPress)
                            copyAction(value)
                        },
                        onAction = onAction
                    )
            )
        val rowGestureModifier =
            if (copyable) {
                Modifier.raftGesturePointerInput(gestureOwner, row.copyValue, row.enabled) { owner ->
                    var gesture: RaftGestureSession<SharedSettingsRowGestureCallbacks>? = null
                    detectTapGestures(
                        onPress = {
                            gesture = owner.beginGesture()
                            tryAwaitRelease()
                        },
                        onTap = {
                            (gesture ?: owner.beginGesture()).currentCallbacksOrNull()?.let { callbacks ->
                                if (callbacks.row.enabled) {
                                    callbacks.onAction(
                                        callbacks.row.key,
                                        callbacks.row.value.takeIf { it.isNotBlank() }
                                    )
                                }
                            }
                        },
                        onLongPress = {
                            (gesture ?: owner.beginGesture()).currentCallbacksOrNull()?.let { callbacks ->
                                callbacks.onCopyValue?.invoke(callbacks.row.copyValue)
                            }
                        }
                    )
                }
            } else {
                Modifier.clickable(enabled = row.enabled) { onAction(row.key, row.value.takeIf { it.isNotBlank() }) }
            }
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .background(RaftColor.Card)
                .then(rowGestureModifier)
                .padding(horizontal = 14.dp, vertical = 12.dp),
            verticalAlignment = androidx.compose.ui.Alignment.CenterVertically,
            horizontalArrangement = Arrangement.spacedBy(10.dp)
        ) {
            Box(
                modifier = Modifier.size(34.dp).background(if (row.enabled) RaftColor.AccentCyan else RaftColor.EmptyStateGray, RoundedCornerShape(RaftAppRadius.Sticker)).border(RaftAppStroke.Control, if (row.enabled) RaftColor.StickerInk else RaftColor.BorderBlack, RoundedCornerShape(RaftAppRadius.Sticker)),
                contentAlignment = androidx.compose.ui.Alignment.Center
            ) {
                RaftLucideIcon(
                    row.iconName,
                    modifier = Modifier.size(18.dp),
                    color = if (row.enabled) raftArgbHex(RaftColor.StickerInk) else RaftColor.TextBlackArgb
                )
            }
            Column(modifier = Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(3.dp)) {
                Row(horizontalArrangement = Arrangement.spacedBy(8.dp), verticalAlignment = Alignment.CenterVertically) {
                    Text(
                        row.title,
                        modifier = Modifier.weight(1f, fill = false),
                        style = RaftType.Button.copy(color = RaftColor.TextBlack),
                        color = RaftColor.TextBlack,
                        maxLines = 1,
                        overflow = TextOverflow.Ellipsis
                    )
                    row.badgeLabel.takeIf { it.isNotBlank() }?.let {
                        SettingsConnectedAppsBadge(it, RaftColor.BrandYellow)
                    }
                }
                row.detail.takeIf { it.isNotBlank() }?.let {
                    Text(it, style = RaftType.Caption.copy(color = RaftColor.TextMutedGray), color = RaftColor.TextMutedGray, maxLines = 2, overflow = TextOverflow.Ellipsis)
                }
                row.supportingDetail.takeIf { it.isNotBlank() }?.let {
                    Text(it, style = RaftType.Caption.copy(color = RaftColor.TextMutedGray), color = RaftColor.TextMutedGray, maxLines = 1, overflow = TextOverflow.Ellipsis)
                }
            }
            row.status.takeIf { it.isNotBlank() }?.let {
                Text(it, style = RaftType.Caption.copy(color = RaftColor.TextMutedGray), color = RaftColor.TextMutedGray, maxLines = 1)
            }
            row.toggleValue?.let { enabled ->
                RaftSwitchButton(checked = enabled, enabled = row.enabled)
            }
        }
    }
}

private data class SharedSettingsRowGestureCallbacks(
    val row: RaftSharedSettingsRow,
    val onCopyValue: ((String) -> Unit)?,
    val onAction: (String, String?) -> Unit
)

@Composable
internal fun SharedSettingsAboutContent(
    state: ScreenLoadState<SharedSettingsAboutSnapshot>,
    fallback: SharedSettingsAboutSnapshot,
    developerState: ScreenLoadState<SharedSettingsDeveloperSnapshot> = ScreenLoadState.Loading,
    includeDeveloperShortcuts: Boolean = false,
    updateCheck: SharedSettingsUpdateCheckSnapshot?,
    actionState: SharedSettingsActionState?,
    bottomContentPadding: Dp = RaftAppSpacing.Lg,
    onCopyBuild: (String) -> Unit,
    onCopyValue: ((String) -> Unit)? = null,
    webUrl: String = SharedSettingsDefaultWebBaseUrl,
    onOpenRaft: (String) -> Unit,
    onCheckHandsUpdate: () -> Unit,
    onPrefetchReleaseNotes: suspend (String) -> Unit = {},
    onOpenSourceLicenses: () -> Unit,
    onCopyEnvironmentInfo: () -> Unit,
    onOpenApiEnvironment: () -> Unit,
    onOpenDiagnostics: () -> Unit,
    onSendFeedback: (() -> Unit)? = null
) {
    val snapshot =
        when (state) {
            is ScreenLoadState.Content -> state.data
            else -> fallback
        }
    val releaseNotesUrl =
        remember(snapshot.buildLabel) {
            releaseNotesSanitizeVersionCode(snapshot.buildLabel)
                .takeIf(String::isNotBlank)
                ?.let(::sharedSettingsReleaseNotesUrl)
                .orEmpty()
        }
    LaunchedEffect(releaseNotesUrl) {
        releaseNotesUrl.takeIf(String::isNotBlank)?.let { onPrefetchReleaseNotes(it) }
    }
    val aboutPayload =
        snapshot.toAboutPayload(
            webUrl = webUrl,
            errorStrings = localizedErrorPresentationStrings(),
            updateCheck = updateCheck,
            actionState = actionState,
            copy = settingsAboutPayloadCopy(sharedSettingsResolvedWebBaseUrl(webUrl))
        )
    val developer = (developerState as? ScreenLoadState.Content<SharedSettingsDeveloperSnapshot>)?.data
    val environmentStatus =
        when (developerState) {
            ScreenLoadState.Loading -> stringResource(MR.strings.settings_state_loading)
            is ScreenLoadState.Content -> developer?.environmentLabel.orEmpty().ifBlank { stringResource(MR.strings.settings_developer_state_current) }
            else -> stringResource(MR.strings.settings_state_unavailable)
        }
    val environmentDetail =
        developer?.apiBaseUrl.orEmpty().ifBlank {
            stringResource(MR.strings.settings_developer_environment_detail)
        }
    val payload =
        if (includeDeveloperShortcuts) {
            aboutPayload.copy(
                sections =
                    aboutPayload.sections +
                        RaftSharedSettingsSection(
                            title = stringResource(MR.strings.settings_developer_section_api_server),
                            rows = settingsAboutDeveloperShortcutRows(
                                environmentTitle = stringResource(MR.strings.settings_developer_api_environment),
                                environmentDetail = environmentDetail,
                                environmentStatus = environmentStatus,
                                environmentEnabled = developerState is ScreenLoadState.Content,
                                diagnosticsTitle = stringResource(MR.strings.settings_diagnostics_title),
                                diagnosticsDetail = stringResource(MR.strings.settings_developer_diagnostics_detail),
                                feedbackTitle = stringResource(MR.strings.settings_feedback_title),
                                feedbackDetail = stringResource(MR.strings.settings_feedback_subtitle),
                                openStatus = stringResource(MR.strings.settings_state_open),
                                includeFeedback = onSendFeedback != null
                            )
                        )
            )
        } else {
            aboutPayload
        }
    SharedSettingsSectionContent(payload, bottomContentPadding = bottomContentPadding, onCopyValue = onCopyValue) { action, value ->
        when (action) {
            "copyBuild" -> onCopyBuild(value.orEmpty().ifBlank { snapshot.buildSummary() })
            "openSlock" -> onOpenRaft(value.orEmpty().ifBlank { webUrl })
            DEVELOPER_ACTION_HANDS_UPDATE_CHECK -> onCheckHandsUpdate()
            "openSourceLicenses" -> onOpenSourceLicenses()
            "copyEnvironmentInfo" -> onCopyEnvironmentInfo()
            DEVELOPER_ACTION_API_ENVIRONMENT -> onOpenApiEnvironment()
            "diagnostics" -> onOpenDiagnostics()
            SETTINGS_ABOUT_FEEDBACK_ACTION -> onSendFeedback?.invoke()
        }
    }
}

internal const val SETTINGS_ABOUT_FEEDBACK_ACTION = "sendFeedback"

internal fun settingsAboutDeveloperShortcutRows(
    environmentTitle: String,
    environmentDetail: String,
    environmentStatus: String,
    environmentEnabled: Boolean,
    diagnosticsTitle: String,
    diagnosticsDetail: String,
    feedbackTitle: String,
    feedbackDetail: String,
    openStatus: String,
    includeFeedback: Boolean
): List<RaftSharedSettingsRow> =
    buildList {
        add(
            RaftSharedSettingsRow(
                key = DEVELOPER_ACTION_API_ENVIRONMENT,
                iconName = RaftLucideIconName.Server,
                title = environmentTitle,
                detail = environmentDetail,
                status = environmentStatus,
                enabled = environmentEnabled,
                copyValue = environmentDetail
            )
        )
        add(
            RaftSharedSettingsRow(
                key = "diagnostics",
                iconName = RaftLucideIconName.ClipboardList,
                title = diagnosticsTitle,
                detail = diagnosticsDetail,
                status = openStatus,
                enabled = true
            )
        )
        if (includeFeedback) {
            add(
                RaftSharedSettingsRow(
                    key = SETTINGS_ABOUT_FEEDBACK_ACTION,
                    iconName = RaftLucideIconName.MessageSquarePlus,
                    title = feedbackTitle,
                    detail = feedbackDetail,
                    status = openStatus,
                    enabled = true
                )
            )
        }
    }

