    val system = this
    if (system == null) {
        return listOf(
            section.toPlaceholderRow(
                "system_channels",
                RaftLucideIconName.Eye,
                sectionTitle,
                "System channel controls are unavailable.",
                errorStrings
            )
        )
    }
    if (system.allChannelId.isBlank()) {
        return listOf(
            section.toPlaceholderRow(
                "system_channels",
                RaftLucideIconName.Eye,
                sectionTitle,
                "No #all channel was found for this workspace.",
